quests[31209] = { id = 31209, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Finstere Schwinge, finstere Dinge", description = "Zur Erstellung meines ersten Giftes brauche ich eine weitere Zutat, <Erwecker/Erweckerin>.\n\nIhr findet sie ganz einfach bei den Skarabäen hier in der Nähe.\n\nTötet sie und bringt mir ihre Flügel.", sourceObjective = "Sammelt 150 Skarabäenflügel.", progress = "Skarabäenflügel können zerstoßen werden, um ein sehr feines und tödliches weißes Pulver herzustellen.", completion = "Ja, ausgezeichnet, Erwecker! Die hier sind perfekt.\n\nHabt Ihr Euch schon einmal überlegt, die Giftkunst zu erlernen?", sourceObjectiveStatus = "unverified-source-field" }
quests[31210] = { id = 31210, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Schatten des Schreckens", description = "Die letzte Zutat ist vielleicht die tödlichste.\n\nDie Angstschattenblume wächst überall hier auf diesen Hügeln.\n\nIhr Verzehr ist dafür verantwortlich, dass die hiesigen Tiere so giftig sind.\n\nEin einziger Tropfen Angstschattennektar reicht, um das Herz eines Kunchong zum Stillstand zu bringen.\n\nZieht los und bringt mir ein paar von diesen Blumen. Lasst Euch nicht dazu verlocken, sie zu kosten.", sourceObjective = "Sammelt 8 Angstschatten.", progress = "Manchmal sind die schönsten Dinge auch die gefährlichsten.", completion = "Nicht viele würden den Wert dessen erkennen, was Ihr habt.\n\nGut gemacht, Erwecker.", sourceObjectiveStatus = "unverified-source-field" }
quests[31211] = { id = 31211, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der vergiftete Geist", description = "Bevor wir nach Klaxxi'vess zurückkehren, möchte ich einen Blick auf das Reich werfen. Der Rat der Klaxxi hat mir berichtet, dass der Feind sich vor dem Palast der Kaiserin sammelt.\n\nMeine Gifte sind bereit, denn wie könnte ich meine Rückkehr besser verkünden als mit Tod und Zerstörung?\n\nPasst nur auf, dass Ihr die beiden Seren nicht vermischt... zumindest nicht, solange Ihr die Gefäße noch in der Hand haltet.\n\nSprecht mit mir, wenn Ihr zum Abflug bereit seid.", sourceObjective = "Sprecht mit Xaril dem vergifteten Geist. Tötet 200 Mantis und 3 Kunchong, während Ihr mit ihm fliegt.", completion = "Danke, dass Ihr mich nach Hause zurückgebracht habt, Erwecker, ich fürchte allerdings, dass der Krieg gerade erst beginnt.", sourceObjectiveStatus = "unverified-source-field" }
quests[31212] = { id = 31212, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "FLAGGE - Tenwu gewählt" }
quests[31213] = { id = 31213, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "FLAGGE - Taoshi gewählt" }
quests[31214] = { id = 31214, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "FLAGGE - Nurong gewählt" }
quests[31216] = { id = 31216, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Himmel verfinstert sich", description = "Der Schwarm fängt an, <Erwecker/Erweckerin>! Die Mantis sammeln sich im Herzen der Angst.\n\nSie füllen den Himmel bereits mit ihren Flügeln und zerfetzen die Erde mit ihren Klauen. Sie werden ihren finsteren Marsch erst unterbrechen, wenn ihre Körper offen und blutend auf dem Boden liegen.\n\nUnd das werden wir mit Freuden tun. Wir werden von oben angreifen. Nutzt meine Gifte, um ihre Vorhut zu vernichten, während ich fliege.\n\nAber vermischt die Seren nicht, bis Ihr bereit seid, anzugreifen. Die Reaktion kann recht... heftig sein.\n\nSprecht mit mir, wenn Ihr so weit seid.", sourceObjective = "Tötet 200 Mantis und 3 Kunchong oder grauenhafte Ungetüme, während Ihr mit Xaril dem vergifteten Geist fliegt.", progress = "Diese wunderbare Zerstörung!", completion = "Gut gemacht, Erwecker. Ihr habt die Zielgenauigkeit eines Zerstörers.", sourceObjectiveStatus = "unverified-source-field" }
quests[31218] = { id = 31218, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "FLAGGE - Tenwu freigespielt" }
quests[31219] = { id = 31219, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "FLAGGE - Nurong freigespielt" }
quests[31220] = { id = 31220, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Ring des Herausforderers: Falkenmeister Nurong", description = "Ihr verdient Euch immer mehr Respekt bei den Shado-Pan, {name}.\n\nNurong möchte seine Fähigkeiten gegen Euch auf die Probe stellen.\n\nDas Gute daran: Wenn Ihr gewinnt, werde ich ihm erlauben, sich Euch auf Euren Missionen anzuschließen.\n\nDer Haken daran: Ich glaube eigentlich nicht, dass Ihr gegen ihn gewinnen könnt.", sourceObjective = "Fordert Falkenmeister Nurong heraus und besiegt ihn im Kampf in der Shado-Pan-Garnison in der Tonlongsteppe.", progress = "Keine Lust auf diese Herausforderung? Kann ich verstehen.", completion = "Tja... Offenbar habe ich mich getäuscht.\n\nGute Arbeit. Nurong wird Euch fortan gerne auf Euren Missionen begleiten.", sourceObjectiveStatus = "unverified-source-field" }
quests[31221] = { id = 31221, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Ring des Herausforderers: Tenwu der Rote Rauch", description = "So... Der berüchtigte Tenwu der Rote Rauch hat Euch also herausgefordert.\n\nDiesen Namen hat er sich übrigens selbst gegeben. Er ist ein guter Kämpfer und Schurke. Allerdings muss man sich wundern, wie er sich so gut an seine Gegner anschleichen kann, wo er doch immerzu lautstark prahlt.\n\nAuf jeden Fall solltet Ihr die Herausforderung annehmen. Vielleicht könnt Ihr ihn etwas Demut lehren. Vielleicht auch nicht. Wenn Ihr aber gewinnen könnt, wird er Euch wohl auf Euren Missionen begleiten wollen. \n\nUnd ich darf mich auf gute Unterhaltung freuen.", sourceObjective = "Fordert Tenwu den Roten Rauch heraus und besiegt ihn im Kampf in der Shado-Pan-Garnison in der Tonlongsteppe.", completion = "Respekt! Gut gemacht. Eure Kampffähigkeiten sind beachtlich.\n\nVielleicht wird er sich ja in Zukunft darauf konzentrieren, mit Euch mitzuhalten, und endlich seine große Klappe halten.", sourceObjectiveStatus = "unverified-source-field" }
quests[31228] = { id = 31228, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Prophet Khar'zul", description = "Prophet Khar'zul ist ein mächtiger Zauberer, aber er unterschätzt auch Eure Fähigkeiten.\n\nKhar'zul und seine Streitkräfte müssen vernichtet werden, um dieses Dorf zu beschützen. Sein Tod wird dem Donnerkönig ein deutliches Zeichen setzen, dass wir uns nicht so einfach besiegen lassen!\n\nIhr findet ihn auf der Insel der Abrechnung.", sourceObjective = "Besiegt Prophet Khar'zul.", progress = "Ist Khar'zul tot?", completion = "Aus diesen Ereignissen sollte man lernen, {name}.\n\nEs ist wichtig, dass wir aus unserer Geschichte Lehren ziehen. Wenn wir der Geschichte Aufmerksamkeit gewidmet hätten, wäre es uns vielleicht möglich gewesen, das hier früher abzuwenden.\n\nAlles Geschehene war bereits vorhergesagt, wir wussten es nur nicht zu deuten.", sourceObjectiveStatus = "unverified-source-field" }
quests[31230] = { id = 31230, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Willkommen in Morgenblüte", description = "Cho ist unterwegs auf einem seiner Abenteuer und dieses Mal wird ein großer Batzen Jade benötigt. Ich werde wohl ein paar ausstehende Gefallen einlösen.\n\nWie wäre es, wenn Ihr Euch in der Zwischenzeit einigen der Einheimischen vorstellt?\n\nEs wäre gut, Kai Wanderbräu und Meister Windpelz kennenzulernen. Oh, und grüßt Peiji Zapfgold drüben beim Gasthaus von mir.\n\nMit den dreien solltet Ihr schon mal einen guten Eindruck vom Leben in Morgenblüte erhalten.", sourceObjective = "Sprecht mit Kai Wanderbräu, Meister Windpelz und Peiji Zapfgold in Morgenblüte.", progress = "Glück gehabt?", completion = "Gut, gut, gut. Ihr werdet hier richtig gut reinpassen.", sourceObjectiveStatus = "unverified-source-field" }
quests[31231] = { id = 31231, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Auslöschung der Schreckensspinner", description = "Auf der Terrasse von Gurthan, wo Ihr mich gefunden habt, ziehen Schreckensspinner weiterhin die Aufmerksamkeit der Shado-Pan-Bogenschützen auf sich, die sich sonst darum kümmern könnten, diesen elenden Schwarm zu lichten.\n\nMerzt die Spinnen aus und entlastet die Bogenschützen auf der Mauer.", sourceObjective = "Tötet 8 Schreckensspinnerhüter auf der Terrasse von Gurthan. Bittet Kil'ruk den Windschnitter, Euch dort abzusetzen.", completion = "Ich konnte Spinnen noch nie leiden. Widerliche, stumpfsinnige Insekten.", sourceObjectiveStatus = "unverified-source-field" }
quests[31232] = { id = 31232, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein uraltes Reich", description = "Meine Brüder reden von einem uralten Mogureich, das einst in den Ruinen im Osten existierte.\n\nDieser Stamm kannte einst unbeschreibliche Geheimnisse über die Zauberei und Unterwerfung.\n\nIch bin sehr wissbegierig, <Erwecker/Erweckerin>, und möchte mehr über die Reiche herausfinden, die nach meiner Zeit existierten.\n\nDas Wissen über die Vergangenheit bestimmt unsere Zukunft.\n\nSucht in den Ruinen nach ihren alten Tafeln. Ich werde ihre Geheimnisse studieren und sie mir zu eigen machen.", sourceObjective = "Sammelt 8 Gurthanitafeln.", progress = "Welches Wissen bringt Ihr?", completion = "Sehr gut, Erwecker. Diese Tafeln zu entziffern wird Zeit in Anspruch nehmen, doch alles Wissen ist es wert.", sourceObjectiveStatus = "unverified-source-field" }
quests[31233] = { id = 31233, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Saft anzapfen", description = "Östlich von hier steht ein Wäldchen mit jungen Bernbäumen, <Erwecker/Erweckerin>.\n\nIch habe Zapfvorrichtungen an den Bäumen angebracht, hatte aber zu viel zu tun, um den Saft einzusammeln.\n\nIch brauche jemanden, der die Entsafter findet. Aktiviert sie und bringt mir dann Proben von dem Bern.", sourceObjective = "Sammelt 6 Portionen Bernsaft.", progress = "Diese Bäume sind noch jung. Sie sind noch keine Kypari.\n\nIhr Saft ist wie Wasser, während der Saft eines echten Kyparibaums Wein ähnelt.\n\nSie müssen weiterwachsen.", completion = "Oh ja, genau das habe ich gebraucht.\n\nIch werde diese Proben untersuchen. Wir müssen die Gesundheit dieser jungen Kypari weiter überwachen.", sourceObjectiveStatus = "unverified-source-field" }
quests[31234] = { id = 31234, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Auge ausstechen", description = "Ah! <Erwecker/Erweckerin>! Ihr müsst mir helfen! (Helft mir, sonst verhelfe ich mir zu Euch!)\n\nIch brauche mehr Material für meine Experimente, oh ja! (Blut und Eingeweide, Herzen und Hirne, Zungen und Augen, Augen, Augen!)\n\nWestlich von hier habe ich Kreaturen aus Nebel und Dunst gesehen. Sie besitzen solch große, runde, wunderbare Kugeln! Groß, um zu sehen, rund und unverwandt!\n\nGeht schon, <kleiner Erwecker/kleine Erweckerin>. Geht und bringt mir ein makelloses Auge!", sourceObjective = "Sammelt 1 makelloses Morastbestienauge.", progress = "Ooooh, welche großartigen, leckeren Teile habt Ihr mir denn gebracht?", completion = "Ja, ja! Wunderbar! Ach, wie köstlich!", sourceObjectiveStatus = "unverified-source-field" }
quests[31235] = { id = 31235, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pfui, noch mehr Spinnen", description = "Diese Waffe habe ich vor Kurzem bei einem Spähgang in der Nähe der Mauer gefunden. Sie sieht genau richtig aus, um Euren Shado-Pan mit ihrer Plage auf der Terrasse von Gurthan zu helfen.\n\nJe mehr sie sich darauf konzentrieren, die Spinnen von der Mauer fernzuhalten, umso weniger Zeit bleibt ihnen zum Töten verängstigter Schwarmgeborener.", sourceObjective = "Benutzt das Drachengewehr der Shado-Pan, um 20 Schreckensspinnereier auf der Terrasse von Gurthan zu zerstören.", completion = "Eine primitive Waffe, doch sie hat ihre Berechtigung.", sourceObjectiveStatus = "unverified-source-field" }
quests[31237] = { id = 31237, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Terrasse von Insekten befreien", description = "Wenn diese Kaiserin tatsächlich von Furcht und Verfolgungswahn befallen ist, hat sie sicherlich Kundschafter in alle Winkel des Landes entsandt, um ihre Kontrolle zu festigen.\n\nDiese Kundschafterlarven sind vermutlich überall, doch schwierig mit bloßem Auge zu entdecken. Über die Pheromonspur, die sie hinterlassen, kann man sie leichter aufspüren.\n\nIch habe Euch bereits ein reaktives Toxin... geschenkt, das Euch vorübergehend, nachdem Ihr den Siegestaumel durchlebt habt, diese Spuren erkennen lässt.\n\nBrecht jetzt zur Terrasse von Gurthan auf und findet diese Spione.", sourceObjective = "Zerstampft 6 Augen der Kaiserin auf der Terrasse von Gurthan. Wenn Ihr etwas tötet, wird Euch die Pheromonfährtensuche bei der Aufstöberung helfen.", progress = "Fragt lieber nicht, wie ich Euch mit dem Toxin infiziert habe - Ihr habt Euch als ziemlich nützlich für uns erwiesen und es wäre schade, wenn wir Euch jetzt vor Schreck in den Wahnsinn treiben würden.", completion = "Information ist Macht, {name}. Wir dürfen nicht zulassen, dass die Kaiserin unsere Bewegungen überwacht.", sourceObjectiveStatus = "unverified-source-field" }
quests[31238] = { id = 31238, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nahrung fürs Hirn", description = "Kovoks Wachstum ist beschleunigt, möglicherweise kann jedoch sein Gehirn nicht Schritt halten. Er braucht eine spezielle Ernährung, damit er nicht die Kontrolle über seinen eigenen Körper verliert.\n\nMushanzungen sind reich an Nährstoffen, die das Wachstum von Kunchonggehirnen fördern, doch normalerweise fressen sie die Tiere ganz und werden schnell satt. Wenn wir Kovok etwa alle paar Tage nur mit Mushanzungen füttern, sollte das sein Wachstum ausgleichen.\n\nIn den Hügeln östlich von hier, nicht weit von der Terrasse von Gurthan, grasen Großrückenmushan.", sourceObjective = "Bringt 4 Mushanzungen zu Kaz'tik dem Manipulator in Klaxxi'vess.", progress = "Habt Ihr eine passende Mahlzeit für Kovok gefunden?", completion = "Während Ihr fort wart, hat Kovok die ganze Zeit gewinselt. Es war so richtig herzergreifend.", sourceObjectiveStatus = "unverified-source-field" }
quests[31239] = { id = 31239, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Name ist gut, Name Name ist besser!", description = "Du willst also ein Ho-zen sein, hä, Nappel?\n\nHo-zen verteidigen ihr Land vor Feinden, wie Jinyu.\n\nKah Kah hat viele Kämpfe mit Jinyu geschlagen und alle gewonnen.\n\nHo-zen geben nur guten Flotschern zwei Namen. Geh und flotsch Jinyu und vielleicht nennen wir dich {name} {name}.\n\nJinyu kriechen am Fluss rum. Flotsch sie bis es dommelt!", sourceObjective = "Tötet 7 Strandläufer der Jinyu.", completion = "Ha ha! Nappel hat verfiddelte Jinyu geflotscht!", sourceObjectiveStatus = "unverified-source-field" }
quests[31240] = { id = 31240, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Guo-Lai-Befall", description = "Anji war hier und hat nach Euch gefragt. Sagte, sie war auf dem Weg nach Nordosten, in die Ruinen.\n\nOh, Anji ist wirklich ein zorniger Charakter! Ist auf lange Sicht vielleicht besser für Eure Gesundheit, wenn Ihr sie nicht warten lasst.", sourceObjective = "Sprecht mit Anji Herbstlicht in den Guo-Lai-Ruinen.", sourceObjectiveStatus = "unverified-source-field" }
quests[31241] = { id = 31241, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fiese Nappels", description = "{name} <guter/gute> Nappel, heißt es…\n\n{name} helfen Ho-zen, heißt es…\n\nnicht mehr {name} flotschen, heißt es.\n\nDas in Ordnung. Da drüben gucken. Fiese Nappels fallen runter wie Regen, die kann man flotschen!\n\nGeh und hab Spaß. Aber nicht vergessen, Häuptling Kah Kah kriegt die Schimmerlinge! Das ist Regel von Ho-zen Nummer zwei.\n\n<Jik Jik kratzt sich am Kopf.>\n\nHmm, alle Regeln von Ho-zen sind Nummer zwei...", sourceObjective = "Sammelt 6 Dienstmedaillons der Allianz von kampferprobten Fallschirmjägern.", progress = "Haste was, Nappel?", completion = "Nappelgeflotsche machen Ho-zen reich mit Schimmerlingen!\n\n{name} macht guten zweiten Eindruck. Und für Ho-zen, Nummer Zwei ist am wichtigsten!", sourceObjectiveStatus = "unverified-source-field" }
quests[31242] = { id = 31242, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nebelhauch", description = "Meine Späher haben zwar heute nichts über Mogu in der Nähe des Dorfes berichtet, dafür aber von Problemen mit den Tieren in der Gegend und Geistern am Friedhof. Ich habe Che entsandt, um die Situation zu evaluieren, aber er wird sicher Eure Hilfe brauchen.\n\nBitte begebt Euch nach Südwesten in das Dorf und trefft dort Che. Bietet ihm jede erdenkliche Hilfe an.", sourceObjective = "Sprecht mit Che Wildmarsch in Nebelhauch.", sourceObjectiveStatus = "unverified-source-field" }
quests[31243] = { id = 31243, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Angriff auf Nebelhauch", description = "In Nebelhauch, im Südwesten, sind Mogu gesichtet worden. Ich habe schon Rook und Sun entsandt, aber ich brauche dort noch jemanden mit Fähigkeiten wie Euren.\n\nBitte macht Euch sofort auf den Weg. Die Dorfbewohner brauchen Eure Hilfe.", sourceObjective = "Sprecht mit Sun Zartherz in Nebelhauch.", sourceObjectiveStatus = "unverified-source-field" }
quests[31244] = { id = 31244, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Guo-Lai-Lager", description = "Leven war ganz schön sauer und sagte etwas über Mogu in den Ruinen.\n\nIhr solltet ihn am besten suchen. Leven ist nicht witzig, wenn er sauer ist.", sourceObjective = "Sprecht mit Leven Morgenklinge in den Guo-Lai-Ruinen.", sourceObjectiveStatus = "unverified-source-field" }
quests[31245] = { id = 31245, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nebelhauch", description = "Che hat auf seinem Weg ins Dorf nach Euch gefragt, aber ich sagte ihm, ich hätte Euch nicht gesehen.\n\nWenn Ihr also wollt, könnt Ihr ihn jetzt aufsuchen. Aber auf diese Weise müsst Ihr Euch nicht verpflichtet fühlen! Das war doch klug bedacht von mir, nicht wahr?", sourceObjective = "Sprecht mit Che Wildmarsch in Nebelhauch.", sourceObjectiveStatus = "unverified-source-field" }
quests[31246] = { id = 31246, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Angriff auf Nebelhauch", description = "Ich sehe Rauch aus dem Dorf aufsteigen. Und dieses Mal ist es nicht meine Schuld!\n\nIhr solltet Euch dorthin aufmachen und Eure Hilfe anbieten.", sourceObjective = "Sprecht mit Rook Steinzeh in Nebelhauch.", sourceObjectiveStatus = "unverified-source-field" }
quests[31247] = { id = 31247, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Garnison der Untergehenden Sonne", description = "Anji und Kun haben hier auf dem Weg zur Garnison Rast gemacht. Ein hübsches Paar, findet Ihr nicht? So verschieden und doch so innig miteinander... Ah, wenn ich nur daran denke, geht mir das Herz auf.\n\nSie haben übrigens nach Euch gefragt. Vielleicht wollen sie ja, dass Ihr an ein paar Ausbildungseinheiten teilnehmt? Jedenfalls hoffe ich, dass sie nichts Unanständiges mit Euch vorhaben...", sourceObjective = "Sprecht mit Anji Herbstlicht in der Garnison der Untergehenden Sonne.", sourceObjectiveStatus = "unverified-source-field" }
quests[31248] = { id = 31248, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Guo-Lai-Ruinen", description = "Ich habe Anji und Kun aufgetragen, die Erkundung der Guo-Lai-Ruinen fortzusetzen. Wir haben zwar heute keine Meldungen über die Anwesenheit von Mogu dort erhalten. Aber dennoch scheinen die Ruinen zu den Orten hier im Tal zu zählen, denen ihr größtes Interesse gilt. Vor dem Hintergrund des Angriffs auf das Gebiet am See habe ich die beiden dort auf Patrouille geschickt.\n\nUnd ich möchte, dass Ihr Euch ebenfalls dort einfindet.\n\nBegebt Euch in Richtung Westen am See vorbei bis zu den Ruinen. Anji wird Euch dort weitere Anweisungen geben können.", sourceObjective = "Sprecht mit Anji Herbstlicht bei den Guo-Lai-Ruinen.", sourceObjectiveStatus = "unverified-source-field" }
quests[31249] = { id = 31249, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nebelhauch", description = "Nach allem, was ich gehört habe, ist das Dorf nicht von der Shao-Tien-Offensive betroffen, aber ich möchte kein Risiko eingehen.\n\nIch werde Euch und Che Wildmarsch aussenden, um im Dorf nach dem Rechten zu schauen und den Dorfbewohnern Hilfe anzubieten.", sourceObjective = "Sprecht mit Che Wildmarsch in Nebelhauch.", sourceObjectiveStatus = "unverified-source-field" }
quests[31250] = { id = 31250, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Garnison der Untergehenden Sonne", description = "Wir haben Verluste erlitten, als uns die Mogu über die Goldene Treppe und an unserer Flanke am Weißblütensee angegriffen haben. Unsere Linien sind ausgedünnt.\n\nIch werde Anji und Kun in die Garnison der Untergehenden Sonne entsenden, um unsere Ausbildungsanstrengungen zu verdoppeln. {name}, ich möchte, dass Ihr mit ihnen geht und ihnen zeigt, wie <ein echter/eine echte:c> {class} kämpft.", sourceObjective = "Sprecht mit Anji Herbstlicht in der Garnison der Untergehenden Sonne.", sourceObjectiveStatus = "unverified-source-field" }
quests[31251] = { id = 31251, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Besser essen geht nicht!", description = "Ja, ja.\n\nJeder weiß, dass wir Goblins herumbasteln. Und Sprengstoff machen. Und... Nun, Ihr wisst ja bestimmt auch von den unrühmlichen Sachen.\n\nWas aber niemand weiß, ist, dass ich hervorragend kochen kann! Das ist ein Hobby von mir.\n\nBesorgt uns ein paar leckere Stücke Fleisch von den Tieren aus dieser Gegend, und ich werde uns die besten Mahlzeiten zubereiten, die es ÜBERHAUPT gibt!\n\nUnd ich verspreche auch, nur drei oder vier Prozent Raketentreibstoff zu verwenden.", sourceObjective = "Besorgt 160 Kun-Lai-Fleischbrocken.", progress = "Die Fleischbrocken, {name}? Wir brauchen sie!", completion = "Ihr wisst, was man über's Kochen sagt - LFG. Lecker, frisch... und... Geschirr?", sourceObjectiveStatus = "unverified-source-field" }
quests[31252] = { id = 31252, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zurück zur Westwindruhestätte", description = "Nun, so wie ich die Sache sehe, haben wir viel wiederaufzubauen.\n\nIch bin niemand, der sich einer großen Sache anschließt, aber meine Landarbeiter werden hier nicht viel zu tun haben, um ehrlich zu sein. Und da Ihr ihnen geholfen habt, wollen sie sich Eurer \"Allianz\" anschließen. Warum sollte ich sie also aufhalten?\n\nNehmt sie mit zu Landarbeiter Bo. Sie werden mir zwar fehlen, aber bei Euch sind sie besser aufgehoben.", sourceObjective = "Kehrt zu Landarbeiter Bo in der Westwindruhestätte am Kun-Lai-Gipfel zurück.", completion = "Es war das Richtige, diese Jungs mitzubringen. Wir lassen sie für Euch in null Komma nichts etwas zu essen anpflanzen!", sourceObjectiveStatus = "unverified-source-field" }
quests[31253] = { id = 31253, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zurück zur Ostwindruhestätte", description = "Nun, so wie ich die Sache sehe, haben wir viel wiederaufzubauen.\n\nIch bin niemand, der sich einer großen Sache anschließt, aber meine Landarbeiter werden hier nicht viel zu tun haben, um ehrlich zu sein. Und da Ihr ihnen geholfen habt, wollen sie sich Eurer \"Horde\" anschließen. Warum sollte ich sie also aufhalten?\n\nNehmt sie mit zu Landarbeiter Ko. Sie werden mir zwar fehlen, aber bei Euch sind sie besser aufgehoben.", sourceObjective = "Kehrt zu Landarbeiter Ko in der Ostwindruhestätte am Kun-Lai-Gipfel zurück.", completion = "Es war das Richtige, diese Jungs mitzubringen. Wir lassen sie für Euch in null Komma nichts etwas zu essen anpflanzen!", sourceObjectiveStatus = "unverified-source-field" }
quests[31254] = { id = 31254, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Straße nach Kun-Lai", description = "Ah! Seid gegrüßt, Freund von Lehrensucher Cho. Ich habe eine Nachricht für Euch.\n\n<Die merkwürdige kleine Kreatur reicht Euch einen ramponierten Schriftrollenbehälter.>\n\nDer Lehrensucher erwartet Euch in Kun-Lai. Die Reise dorthin ist äußerst gefährlich, oh ja, äußerst gefährlich.\n\nLasst Euch von den Ortskundigen helfen, denen Ihr auf Eurem Weg begegnet.", sourceObjective = "Reist über die Verhüllte Treppe nach Binan.", progress = "Noch mehr Fremde? Dieser Tag bringt mich an meine Grenzen.", completion = "Oh, Ihr seid ein Freund von Cho? Willkommen! Willkommen!\n\nIch würde Euch ein Bankett auftischen, aber wie Ihr sehen könnt, stecken wir momentan in großen Schwierigkeiten.\n\nWürdet Ihr uns vielleicht helfen?", sourceObjectiveStatus = "unverified-source-field" }
quests[31255] = { id = 31255, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Straße nach Kun-Lai", description = "Ah! Seid gegrüßt, Freund von Lehrensucher Cho. Ich habe eine Nachricht für Euch.\n\n<Die merkwürdige kleine Kreatur reicht Euch einen ramponierten Schriftrollenbehälter.>\n\nDer Lehrensucher erwartet Euch in Kun-Lai. Die Reise dorthin ist äußerst gefährlich, oh ja, äußerst gefährlich.\n\nLasst Euch von den Ortskundigen helfen, denen Ihr auf Eurem Weg begegnet.", sourceObjective = "Reist über die Verhüllte Treppe nach Binan.", progress = "Noch mehr Fremde? Dieser Tag bringt mich an meine Grenzen.", completion = "Oh, Ihr seid ein Freund von Cho? Willkommen! Willkommen!\n\nIch würde Euch ein Bankett auftischen, aber wie Ihr sehen könnt, stecken wir momentan in großen Schwierigkeiten.\n\nWürdet Ihr uns vielleicht helfen?", sourceObjectiveStatus = "unverified-source-field" }
quests[31256] = { id = 31256, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Treibt sie zusammen", description = "Lok'tar, {class}.\n\nWir haben Fortschritte gemacht, aber wir müssen beweglich sein, wenn wir uns hier am Kun-Lai behaupten wollen.\n\nIch sehe nicht viele Worgs, Kodos oder dergleichen in dieser Gegend. Was ich aber sehe, sind Yaks. Unsere Pandarenverbündete haben gesagt, dass sie gute Reittiere abgeben, also nehmen wir halt die.\n\nZieht los, treibt ein paar zusammen und bringt sie hierher, damit unsere Leute auf ihnen reiten können!", sourceObjective = "Treibt 3 Yaks der Wilden Ebenen zusammen und bringt sie zur Ostwindruhestätte.", completion = "Gut gemacht! Nun, ich muss schon sagen, sie sind ziemlich störrisch. Aber sie sollten ausreichen.", sourceObjectiveStatus = "unverified-source-field" }
quests[31260] = { id = 31260, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Meisterprofiteur: Casheen", description = "Ich hab' da eine geniale Idee für eine neue Gaunerei!\n\nBei meinem letzten Flug sah ich eine unglaublich alte Tigerin umherstreifen.\n\nWisst Ihr, was für einen Preis ihr Blut auf dem Schwarzmarkt erzielen würde? Und wenn ich dann noch ein paar Hexenmeistern erzähle, dass das Blut ihren Beschwörungszaubern zusätzliche Kraft verleiht...\n\nAlso wenn Ihr mir etwas von ihrem Blut bringt, beteilige ich Euch an der Gaunerei. Zuletzt habe ich die Tigerin auf der anderen Seite des Dojani gesehen.", sourceObjective = "Sammelt das Blut der alten Tigerin.", progress = "Ich hatte mir ja schon überlegt, es selbst mit dieser Tigerin aufzunehmen, aber ich hänge zu sehr an meinem Leben, um ehrlich zu sein...", completion = "Beeindruckend! Riecht Ihr schon das Geld? Hier ist Euer Anteil.", sourceObjectiveStatus = "unverified-source-field" }
quests[31261] = { id = 31261, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kapitän Jack ist tot", description = "Halb geronnenes Blut tropft aus Kapitän Jacks Kopf auf den Boden und versiegt dort, als Ihr Eure hart erkämpfte Trophäe begutachtet.\n\nSeltsam, aber Ihr habt jetzt keine Zeit, das zu untersuchen. Zu viel Arbeit muss erledigt werden.\n\nDer Häuptling Eurer neuen Freunde wird sicherlich beeindruckt sein von diesem Beweis Eurer Flotschfähigkeiten.", sourceObjective = "Bringt Kapitän Jacks Kopf zu Häuptling Kah Kah in Flotschhügel.\n\nBereitgestellter Gegenstand:", completion = "Verfiddelter Flotsch, Nappel!", sourceObjectiveStatus = "unverified-source-field" }
quests[31262] = { id = 31262, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kranichbeherrschung: Dolchschnabel", description = "Nun, da Ihr ein Gespür für den Kampfstil des Kranichs entwickelt habt, werdet Ihr es mit einem echten Prachtexemplar zu tun bekommen.\n\nDolchschnabel!\n\nZumindest nenne ich den Burschen so. Ist der größte Kranich, den ich je gesehen habe. Und sein Schnabel ist messerscharf.\n\nNordwestlich von hier befindet sich ein großer Wasserfall, aus dem der Dojani entspringt. Dolchschnabel hält sich meistens in der Nähe dieses Wasserfalls auf.\n\nWenn Ihr mir seinen Schnabel als Trophäe bringt, lege ich bei Nesingwary ein gutes Wort für Euch ein.", sourceObjective = "Holt Euch den Dolchschnabel.", progress = "Ich habe gesehen, wie dieser Vogel einem Tiger das Gesicht durchbohrt hat. Wo bitteschön sind wir hier, wenn Tiger zur Beute von Vögeln werden?", completion = "Na DAS nenne ich mal eine Trophäe. Sieht ziemlich einschüchternd aus. Moment... klebt da etwa Euer Blut dran?", sourceObjectiveStatus = "unverified-source-field" }
quests[31265] = { id = 31265, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mazus Atem", description = "Ihr seid also hier, um zu helfen, ja? Na, eins nach dem anderen.\n\n<Arie durchwühlt kurz ihre Taschen und bringt eine kleine Phiole mit einer leuchtenden blauen Flüssigkeit zum Vorschein.>\n\nHier ist es! \"Mazus Atem\". Nach einer Rezeptur des Käpt'n.\n\nWas? Ihr dachtet, ich würde Euch ohne Atemhilfe auf See schicken? Ich brauche Deckhelfer, keine Leichen!\n\nRunter damit, Grünschnabel. Damit habt Ihr dort draußen auf dem Riff eine reelle Chance.", sourceObjective = "Trinkt den Trank aus Mazus Atem.", progress = "Nein, ich habe nichts zum Runterspülen. Trinkt einfach aus!", completion = "Ihr werdet mir noch danken.", sourceObjectiveStatus = "unverified-source-field" }
quests[31266] = { id = 31266, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Einfall der Mogu", description = "Wir haben Berichte über mehrere Mogugruppen erhalten, die hier in Tonlong an der Küste eingefallen sind. Ich habe keine Ahnung, was sie hier tun, und ganz ehrlich: Es ist mir auch egal.\n\nIhr habt Euch bewiesen, daher wollen wir Euch diese Mission anvertrauen.\n\nFolgendes wird passieren: Ihr zieht los, findet sie und tötet sie alle.\n\nUnsere Späher haben gemeldet, dass die erste Gruppe Richtung Norden gelandet ist, zwischen hier und dem Plateau des Totensprechers. Geht dorthin und schaltet sie aus.", sourceObjective = "Findet und tötet den Spionagemeister der Shan'ze.", progress = "Warum sind sie noch nicht tot?", completion = "Es war nur eine Ablenkung! Sie machen sich bereit, den Niuzaotempel anzugreifen!", sourceObjectiveStatus = "unverified-source-field" }
quests[31267] = { id = 31267, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Vernichtung der Nebelklingen", description = "Korven hat mir erzählt, was er herausgefunden hat. Auf dem Grund des Sternensees gibt es eine gewaltige Bernablagerung.\n\nLeider lebt am Ufer des Sees ein feindseliger Saurokstamm, der den Bern als sein Eigentum betrachtet.\n\nSeine Angehörigen werden uns nicht einfach so in ihr Gebiet vordringen lassen.\n\nBegebt Euch nach Süden zum See. Tötet die Nebelklingensaurok, damit wir den Bern in der Nähe leichter abtragen können.", sourceObjective = "Tötet 6 Reißer der Nebelklingen.", completion = "Gut gemacht. Mit diesem Bern können wir Waffen für unsere Sache fertigen.", sourceObjectiveStatus = "unverified-source-field" }
quests[31268] = { id = 31268, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kleine, graue Zellen", description = "Tief im Süden brütet der Schwarm Vernichtungswaffen aus - riesige Bernskorpione, die so gut wie unzerstörbar sind.\n\nWie alle anderen Kreaturen sind auch sie manipulierbar, im Gegensatz zu anderen Kreaturen haben sie sich aber noch nicht meiner Gedankenkontrolle unterworfen.\n\nWie es scheint, muss ich weitere Forschungen betreiben, ehe es mir gelingt, sie für unsere Zwecke zu beherrschen.\n\nIch muss ihre Gehirne untersuchen, und Eure Aufgabe ist es, mir ein paar Exemplare zu besorgen.\n\nNehmt diesen Schallemitter. Er hat sich als ziemlich wirksam gegen die Biester erwiesen.", sourceObjective = "Sammelt 3 bernverkrustete Gehirne von Bernstechern der Ik'thik.", progress = "Sie widersetzen sich weiterhin meiner Schallmanipulation. Ich muss herausfinden, weshalb.", completion = "Sieh mal einer an, wie interessant. Sie sind anders als alle anderen Gehirne, die ich gesehen habe.\n\nIch werde sie genau untersuchen.", sourceObjectiveStatus = "unverified-source-field" }
quests[31269] = { id = 31269, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Schuppenlord", description = "Die Saurok am Sternensee empfangen ihre Befehle von ihrem Schuppenlord, einem grausamen, gnadenlosen Anführer, der sein Revier erbittert bewacht.\n\nWenn es uns gelingt, diesen Anführer auszuschalten, erhalten wir Zugriff auf die gewaltige Bernader unter dem See.\n\nGeht. Ihr Anführer erteilt seine Befehle von seinem unterirdischen Sitz am südlichen Seeufer aus.", sourceObjective = "Tötet den Schuppenlord der Nebelklingen.", completion = "Gut. Freut mich zu hören, dass er tot ist.", sourceObjectiveStatus = "unverified-source-field" }
quests[31270] = { id = 31270, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Kampf gegen die Angst", description = "Als wir den Einfluss des Sha bei Kypari Zar bemerkten, hatte ich gehofft, die Verderbnis könnte noch geläutert werden.\n\nLeider hat der Rat der Klaxxi bestätigt, dass die Verderbnis des Sha der Angst tief verwurzelt ist und sich weiter ausbreitet.\n\nIm Süden habe ich beobachtet, wie ein Teil der heimischen Tier-und Pflanzenwelt von einem namenlosen Schrecken ergriffen wurde.\n\nDas Sha kann seine Opfer zu furchtbar abscheulichen Kreaturen verzerren.\n\nWir müssen der Verderbnis Einhalt gebieten, bevor sie noch schlimmer wird. Sucht die Sha-verseuchten Schreckensschuppenskorpide. Vernichtet sie.", sourceObjective = "Tötet 15 Schreckensschuppenskorpide.", completion = "Ihr habt die Hügel von den verseuchten Kreaturen befreit? Gut.\n\nDas Sha ist ein gnadenloser Gegner. Also dürfen auch wir ihm keine Gnade zeigen.", sourceObjectiveStatus = "unverified-source-field" }
quests[31271] = { id = 31271, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schlechte Gene", description = "Tief im Süden, <Erwecker/Erweckerin>, führen die Genomanten der Kaiserin ihre finsteren Experimente durch. (Finster, mag schon sein, aber nicht so finster wie meine!)\n\nSie sezieren und verändern die wilden Tiere der Umgebung und erzeugen Kreaturen nach eigenem Gutdünken. (Ihre Entwürfe werden bald meine Entwürfe sein!)\n\nDas dürfen wir nicht zulassen! (Nein, nein! Solche Macht steht nur mir zu!)\n\nIhre Mutationen werden bereits im Krieg eingesetzt. Geht los! Zerstört sie um jeden Preis!", sourceObjective = "Tötet 3 Genomanten der Ik'thik und 6 Eierdrohnen der Ik'thik.", completion = "Ja, ja! Sie sind tot!\n\nDanke, Erwecker. Das habt Ihr gut gemacht.", sourceObjectiveStatus = "unverified-source-field" }
quests[31272] = { id = 31272, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ansteckung", description = "Die Genomanten der Kaiserin spielen mit gefährlichen Spielzeugen.\n\nWeiter im Süden injizieren sie den hiesigen Tieren pheromonhaltige Parasiten, um monströse Mutationen für den Krieg zu erschaffen.\n\nSie waren so nachlässig, dass ihre parasitären Würmer in das örtliche Ökosystem entkommen konnten.\n\nWenn nichts dagegen unternommen wird, breitet sich die Infektion so lange von Tier zu Tier aus, bis wir es mit einer Seuche zu tun haben.\n\nIch werde Euch ein schwaches Toxin injizieren, mit dem Ihr in der Lage sein werdet, angesteckte Kreaturen zu identifizieren.\n\nTötet die Träger auf der Stelle.", sourceObjective = "Tötet 6 infizierte Wildtiere. Infizierte Wildtiere sind Knochenstaubmotten, Blauhautmushan und mutierende Skorpide.", completion = "Die Infektion hatte sich also schon ausgebreitet. Wie es scheint, konntet Ihr die Verbreitung gerade noch stoppen.\n\nIch glaube nicht, dass die Genomanten ihre haarsträubenden Experimente einstellen werden, wir müssen ihre Anstrengungen jedoch weiter vereiteln.", sourceObjectiveStatus = "unverified-source-field" }
quests[31273] = { id = 31273, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Relikte des Schwarms" }
quests[31274] = { id = 31274, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "LFGDungeons - Mists - Raid Finder - 1st" }
quests[31275] = { id = 31275, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "LFGDungeons - Mists - Raid Finder - Nth" }
quests[31277] = { id = 31277, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Überraschungsangriff!", description = "Diese abscheulichen Mogu...\n\nDie Späher waren nur ein Ablenkungsmanöver! Während wir ihre Spione jagten, griff ihre Hauptstreitmacht den Niuzaotempel an. Verderbte Schlangen, überall Mogu... das ist eine Katastrophe!\n\nGlücklicherweise konnte Ban ihre Linien mit den Elitemitgliedern unseres Ordens durchdringen. Wenn dieses Kunststück auch Euch gelingt, stoßt zu ihm. Wir müssen dem ein Ende setzen!", sourceObjective = "Trefft Euch mit Ban Bärenherz am Niuzaotempel in der Tonlongsteppe und setzt der dortigen Moguinvasion ein Ende.", completion = "Niuzao ist gerettet. Die Mogu wurden zurückgeschlagen. Und Ihr, mein Freund, Ihr habt Euch einer großen Ehre als würdig erwiesen. \nWir werden Euch in die Reihen der Shado-Pan aufnehmen.", sourceObjectiveStatus = "unverified-source-field" }
quests[31278] = { id = 31278, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Anleitung zur Questerstellung", description = "Juchu! Ihr dürft eine Schnitzeljagdquest erstellen! Findet heraus, was als Nächstes zu tun ist.", sourceObjective = "Erstellt eine Schnitzeljagdquest.", sourceObjectiveStatus = "unverified-source-field" }
quests[31279] = { id = 31279, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Alles, was ich übers Kochen weiß", description = "Ich bin so froh, dass Euch mein Essen schmeckt. Wärt Ihr vielleicht an den Rezepten interessiert? Falls ja, solltet Ihr sie aus erster Hand von meinen Lehrern vom Halbhügelmarkt lernen. Alles, was ich über die Küche weiß, habe ich bei ihnen gelernt.\n\nUnd wenn Ihr sowieso in diese Gegend kommt, könntet Ihr dann vielleicht Sungshin Eisentatz diese Nachricht überbringen? Sie war meine Lieblingslehrerin. Ich vermisse sie, und ich möchte, dass sie das auch weiß.", sourceObjective = "Überbringt Sungshin Eisentatz den Brief. Sie unterrichtet auf dem Halbhügelmarkt.", progress = "Ihr habt einen Brief für mich?", completion = "Oh, wie aufmerksam. Ich höre immer sehr gerne von meinen ehemaligen Schülern.", sourceObjectiveStatus = "unverified-source-field" }
quests[31280] = { id = 31280, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wie man kocht", description = "Es gibt viele Arten, zu kochen, und jede Methode erschafft einzigartige Gerichte. Die pandarischen Wege des Kochens sind der Weg des Grills, des Woks, des Topfes, des Dampfgarers, des Ofens und des Brauens. Es scheint, als ob Ihr durch Eure Erfahrungen in fernen Ländern bereits die Grundlagen eines jeden Weges beherrscht. Falls Ihr wünscht, noch weiter ausgebildet zu werden, sprecht mit meinen Geschwistern und erlernt das erste fortgeschrittene Rezept, dass jeder von ihnen lehrt. Findet heraus, welcher Weg am besten zu Euch passt.", sourceObjective = "Erlernt die Rezepte für gegrilltes Tigersteak, gebratenen Reis nach Jadewaldart, verwirbelte Nebelsuppe, Garnelenklößchen, Wildgeflügelbraten und Ginsengtee von den Meistern auf dem Halbhügelmarkt.", sourceObjectiveStatus = "unverified-source-field" }
quests[31281] = { id = 31281, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ihr wollt also Koch werden…", description = "Ihr wollt <Koch/Köchin> werden? Wenn Ihr wirklich Eure volle Hingabe beweist, kann ich Euer verborgenes Potenzial verwirklichen, egal, wie unerfahren Ihr seid.\n\nWenn Ihr etwas von mir lernen wollt, dann zeigt mir, dass Ihr zumindest einfachen Anweisungen folgen könnt. Lernt, wie man einen Pfirsich in Scheiben schneidet und zeigt mir dann, was Ihr gelernt habt. Ich kann Euch frische pandarische Pfirsiche zu einem guten Preis verkaufen.", sourceObjective = "Erlernt das Rezept für einen Pfirsich in Scheiben von der Weiserin der Wege und bereitet ihr 5 von ihnen zu.", progress = "Beweist mir, dass Ihr Anweisungen folgen könnt.", completion = "Nun gut. Ihr seid in der Lage, etwas zu lernen. Ich kann Euch viel beibringen, und ich habe die meisten Zutaten, die Ihr braucht, um etwas zu lernen. Ihr könnt Euch von mir unterrichten lassen.", sourceObjectiveStatus = "unverified-source-field" }
quests[31282] = { id = 31282, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Quest Spürt Kaz'tik auf" }
quests[31283] = { id = 31283, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Theramore Destroyed Tracking" }
quests[31284] = { id = 31284, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "FLAG - Ancient Pandaren Fishing Pole" }
quests[31285] = { id = 31285, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Frühlingsbummler", description = "Wer auf eine Begegnung mit ein paar Saurok verzichten möchte, sollte die Uralte Passage nicht zu Fuß bereisen.\n\nIch mache Euch ein Angebot: Eierschale und ich wollten gerade flussaufwärts nach Binan aufbrechen. Sollen wir Euch mitnehmen?", sourceObjective = "Überlebt eine Fahrt mit der Frühlingsbummler.", completion = "Puh... Das wäre geschafft. Willkommen in Binan.", sourceObjectiveStatus = "unverified-source-field" }
quests[31286] = { id = 31286, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Beraubung der Räuber", description = "Ah, <ein/eine:c> {class}. Ich hätte da gerade Verwendung für Eure Fähigkeiten.\n\nOben an der Straße wurde ein Konvoi von einer Bande marodierender Saurok angegriffen. Die Räuber haben ein paar... Waren... entwendet, die Madame Goya veräußern wollte.\n\nEs gleicht einem Sakrileg, Madame Goya zu bestehlen.\n\nWenn es Euch gelingen sollte, diese Waren zurückzuholen, werde ich Euch gerne einen Finderlohn zahlen.", sourceObjective = "Holt 7 Schwarzmarktwaren zurück.", progress = "Die Saurok sind normalerweise nicht so dreist.", completion = "Ah, unsere Waren. Madame Goya wird sehr zufrieden sein. Ihr könnt Euch ihrer Dankbarkeit gewiss sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[31287] = { id = 31287, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Erziehungsprogramm für die Saurok", description = "Die Lenzstraße untersteht dem Schutz unserer verehrten Madame Goya.\n\nUnd um diese Tatsache zu verdeutlichen, scheinen die Saurok im Hassschuppenbau nordöstlich von hier ein \"Erziehungsprogramm\" zu benötigen. Wir haben sie bereits in der Vergangenheit gewarnt, aber offensichtlich haben sie leider ein kurzes Gedächtnis.\n\nBegebt Euch zu ihrem Bau im Nordosten und findet ihren Schamanenanführer. Wenn es Euch gelingt, ihn zu liquidieren, ist Euch der Dank unserer verehrten Dame gewiss - neben einem angemessenen Kopfgeld, versteht sich.", sourceObjective = "Liquidiert Saugfinger.", progress = "Es ist nicht klug, den Herrschaftsanspruch von Madame Goya in Frage zu stellen.", completion = "Die Aufgabe wurde erfüllt und Schuld muss bezahlt werden. Hier ist Eure Belohnung. Seid Euch unseres Dankes gewiss.", sourceObjectiveStatus = "unverified-source-field" }
quests[31288] = { id = 31288, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Forschungsprojekt: Die Mogudynastien", description = "Ah, <ein Entdecker/eine Entdeckerin> - Ihr kommt gerade recht. Ich stehe nämlich kurz davor, einige der dunklen Geheimnisse der Mogu aufzudecken.\n\nAllerdings nicht alle. Sie haben nämlich viele dunkle Geheimnisse. Aber zumindest bin ich ganz kurz davor, zumindest eines der vielen dunklen Geheimnisse aufzudecken.\n\nWenn Ihr also auf Euren Reisen über Mogufragmente stolpert, dann bringt sie mir. Ich werde mich dafür auch erkenntlich zeigen.", sourceObjective = "Bergt 20 archäologische Fragmente der Mogu.", progress = "Es ist gefährlich, die Vergangenheit zu ignorieren.", completion = "Ah! Das sind ein paar sehr schöne Stücke. Wirklich sehr schön. Ich danke Euch, Abenteurer.", sourceObjectiveStatus = "unverified-source-field" }
quests[31289] = { id = 31289, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Forschungsprojekt: Das Pandaren-Reich", description = "Ah, gut, dass Ihr gerade da seid, <Abenteurer/Abenteurerin>. Meine Tochter und ich erforschen nämlich gerade die Historie unseres Volkes und kommen an einer Stelle nicht so recht weiter.\n\nSolltet Ihr auf antiquarische Pandarenobjekte stoßen, dann bringt sie uns bitte. Wir würden einen großen Vorteil aus solchen zusätzlichen Informationen ziehen können.", sourceObjective = "Bergt 20 archäologische Fragmente der Pandaren.", progress = "Es ist gefährlich, die Vergangenheit zu ignorieren.", completion = "Ah! Das sind ein paar sehr schöne Stücke. Wirklich sehr schön. Ich danke Euch, Abenteurer.", sourceObjectiveStatus = "unverified-source-field" }
quests[31291] = { id = 31291, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Geheimnisse der Vergangenheit", description = "Seid Ihr daran interessiert, auch <ein Lehrensucher/eine Lehrensucherin> zu werden? Dann stellt Euch auf viel Graben und viel Lesen und noch mehr Graben und noch mehr Lesen ein.\n\nIch verbringe ganze Tage damit, auf zerbrochene Vasen zu starren und zu überlegen, wie man sie wieder zusammensetzen kann.\n\nAber probiert es ruhig aus. Wenn Ihr eines der Artefakte aus Pandaria vollständig zusammensetzen könnt, wären wir Euch verbunden, wenn Ihr dieses Wissen mit uns teilen könntet.", sourceObjective = "Setzt 1 Artefakt aus Pandaria wieder zusammen.", completion = "Großartig! Ihr habt die Teile fast nahtlos zusammenfügen können. Die Qualität dieser Restaurierung ist ja überragend.\n\nWie habt Ihr das hinbekommen?", sourceObjectiveStatus = "unverified-source-field" }
quests[31292] = { id = 31292, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "FLAG - Ancient Pandaren Woodcutter" }
quests[31293] = { id = 31293, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mogu keine guten Gäste", description = "Leven hat Rook hierher geschickt, um Mogu aufzuhalten. Sind aber mehr Mogu als Rook töten kann.\n\nHelft Ihr? Rook erzählt Leven auch von Eurer Hilfe. Versprochen.", sourceObjective = "Tötet 8 Shao-Tien-Angreifer in Nebelhauch.", sourceObjectiveStatus = "unverified-source-field" }
quests[31294] = { id = 31294, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Guo-Lai-Ruinen", description = "Ich danke Euch von ganzem Herzen für Eure Hilfe. Anji wartet in den Guo-Lai-Ruinen im Nordwesten auf Euch.\n\nBitte begebt Euch dorthin. Und möge Euch Euer Mut niemals verlassen, <junger/junge:c> {class}.", sourceObjective = "Sprecht mit Anji Herbstlicht bei den Guo-Lai-Ruinen.", sourceObjectiveStatus = "unverified-source-field" }
quests[31295] = { id = 31295, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mogu in den Guo-Lai-Ruinen", description = "Danke für Eure Hilfe.\n\nIch würde Euch gern weiterhin Gesellschaft leisten, aber Leven führt einen Angriff gegen die Mogu in den Guo-Lai-Ruinen nordwestlich von hier. Und er kann jeden fähigen Kämpfer gebrauchen.\n\nMögen die Himmlischen Euch beschützen, <junger Mann/junge Dame>.", sourceObjective = "Sprecht mit Leven Morgenklinge in den Guo-Lai-Ruinen.", sourceObjectiveStatus = "unverified-source-field" }
quests[31296] = { id = 31296, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Guo-Lai-Ruinen", description = "Die Dorfbewohner scheinen in Sicherheit zu sein und die Mogu werden langsam zurückgedrängt. Den Rest sollten wir selbst erledigen können. Danke für Eure freundliche Hilfe, {name}.\n\nAnji hat heute morgen eine Gruppe zur Erkundung und Befreiung der Guo-Lai-Ruinen in den Nordwesten geführt. Sicherlich könnte sie dort jemanden mit Euren Talenten gebrauchen. Ihr solltet sie aufsuchen.", sourceObjective = "Sprecht mit Anji Herbstlicht bei den Guo-Lai-Ruinen.", sourceObjectiveStatus = "unverified-source-field" }
quests[31297] = { id = 31297, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Garnison der Untergehenden Sonne", description = "Die Mogu werden diesen Angriff nicht lange aufrechterhalten können. Von jetzt an sollten wir die Situation in den Griff bekommen. Danke für Eure freundliche Hilfe.\n\nAber vielleicht könnt Ihr ja Anji im Ausbildungslager der Untergehenden Sonne aufsuchen? Sie ist damit beauftragt, die Pandarenrekruten auszubilden. Und Ihr könntet ihnen wohl auch noch ein oder zwei Dinge beibringen.", sourceObjective = "Sprecht mit Anji Herbstlicht im Ausbildungslager der Untergehenden Sonne.", sourceObjectiveStatus = "unverified-source-field" }
quests[31298] = { id = 31298, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zouchin Village - Intro Tracking" }
quests[31299] = { id = 31299, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Shomi Ruins Tracking" }
quests[31300] = { id = 31300, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Shomi Beach Tracking" }
quests[31301] = { id = 31301, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Shomi Strand Tracking" }
quests[31302] = { id = 31302, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bereit für Großes", description = "Ihr scheint Euch in der Küche ziemlich gut auszukennen. Zeigt mir, was Ihr könnt, indem Ihr 5 Schüsseln Milchreis zubereitet.", sourceObjective = "Bereitet 5 Schüsseln Milchreis zu und gebt sie der Gewährerin der Einblicke.", progress = "Ich glaube, Ihr habt das Zeug zu einem großen Koch, doch erst der Milchreis wird meine Einschätzung bestätigen.", completion = "Ihr seid bereit. Ihr seid nun ein Zen-Meisterkoch.", sourceObjectiveStatus = "unverified-source-field" }
quests[31303] = { id = 31303, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Siegel ist zerbrochen", description = "<Cho sieht Euch ungläubig an.>\n\nIch... Ich glaubte, Sha von dieser Größe seien ein Mythos - wir alle glaubten das. Wir hielten sie für ein Ammenmärchen, um den Kindern das Kämpfen auszutreiben.\n\nAber für Geplauder bleibt jetzt keine Zeit. Diese Risse, sie nähren es... und machen es jeden Augenblick stärker!\n\nIch muss diese Schriftrollen aus meinen Familienarchiven untersuchen. Ihr, nehmt diese Kanone und reitet Mishi.\n\nIhr müsst einen Weg finden, diesem Schrecken zu begegnen, der auf uns losgelassen wurde!", sourceObjective = "Versiegelt 12 Risse des Sha und verbannt das Sha des Zweifels.", completion = "Ich muss viele Nachforschungen in nur wenig Zeit erledigen.\n\nDie Nachricht des Kaisers warnte nur vor einer einzigartigen Gefahr, die diesem Land Krieg bringen würde - dieses… Sha.\n\nLeider ist die Zeit, seinen Rat zu beherzigen, bereits vorüber. Wie wir nun dieser Krise ein Ende bereiten können, darüber schweigt das Omen des Kaisers.", sourceObjectiveStatus = "unverified-source-field" }
quests[31304] = { id = 31304, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "FLAG - Kafa Press" }
quests[31305] = { id = 31305, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Weg des Grills", description = "Wenn Ihr Essen kocht wollt, dass Euch stärker macht, sucht den Meister des Grills auf. Bereitet für ihn ein Hühnchenspieß mit Erdnusssoße zu, um ihm zu zeigen, dass Ihr die Grundlagen beherrscht.", sourceObjective = "Bereitet ein Hühnchenspieß mit Erdnusssoße zu und gebt es dem Meister des Grills.", sourceObjectiveStatus = "unverified-source-field" }
quests[31306] = { id = 31306, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pfad des Unwissenden", description = "Ich bin mir ziemlich sicher, dass Euer Pandaren-Freund eine Ahnung hat, wonach die Mogu eigentlich suchen.\n\nEr hat sich vor ein paar Tagen ohne Bergführer ins Gebirge aufgemacht und gesagt, dass nur Ihr ihm folgen sollt. Er hatte sich sehr klar ausgedrückt:\n\n\"<Der/Die:c> {class} muss diesen Pfad allein beschreiten, vollkommen konzentriert auf <seine/ihre> eigenen Gedanken. <Er/Sie> soll jedem Schrein die Ehre erweisen, bevor wir uns am Gipfel wiedersehen.\"\n\nDer Pfad beginnt gleich nordwestlich des Lagers und ist durch Flaggen gekennzeichnet. Aber passt gut auf Euch auf! Der Pfad des Unwissenden ist selbst an den harmlosesten Tagen noch gefährlich.", sourceObjective = "Bewältigt den Pfad des Unwissenden, um Euch mit dem Lehrensucher Cho zu treffen. Macht an allen Schreinen entlang des Weges Halt, um Euch dort auf Eure Gedanken zu konzentrieren.", completion = "Ah, Ihr habt es geschafft und den Schreinen Ehre erwiesen.\n\nIch wusste, dass Ihr dazu fähig sein würdet.", sourceObjectiveStatus = "unverified-source-field" }
quests[31307] = { id = 31307, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "FLAG - Jade Infused Blade" }
quests[31308] = { id = 31308, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Erste Erfahrungen", description = "Da Ihr nun <Tierausbilder/Tierausbilderin> seid, ist es an der Zeit, Euer Können auf die Probe zu stellen!\n\nGeht hinaus in den Wald und beginnt einen Kampf mit einem Kampfhaustier. Vergesst nicht, Eure Fertigkeit 'Haustiere aufspüren' einzusetzen, damit Ihr kampfbereite Haustiere auf der Minikarte sehen könnt. Kommt wieder zu mir, nachdem Ihr gewonnen habt, dann setzen wir Eure Ausbildung fort. Viel Glück!", sourceObjective = "Gewinnt einen Haustierkampf.", completion = "Gut gemacht, {name}! Ihr könnt besser mit diesen Tierchen umgehen, als ich dachte!", sourceObjectiveStatus = "unverified-source-field" }
quests[31309] = { id = 31309, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auf dem Wege der Besserung", description = "Nachdem Ihr nun einen Kampf gewonnen habt, müssen wir Eure Haustiere heilen, damit sie wieder einsatzbereit sind! Sucht unsere Stallmeisterin Erma auf, um Eure Haustiere zu heilen und wiederzubeleben.", sourceObjective = "Stattet Erma der Stallmeisterin einen Besuch ab und heilt Eure Tiere vollständig.", completion = "Jetzt strotzen Eure Haustiere ja nur so vor Gesundheit, {name}. Denkt daran, Ihr könnt all Eure Haustiere jederzeit heilen und wiederbeleben lassen, indem Ihr einen Stallmeister aufsucht.", sourceObjectiveStatus = "unverified-source-field" }
quests[31310] = { id = 31310, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verhörsverfolgung" }
quests[31311] = { id = 31311, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Weg des Grills", description = "Der Weg des Grills der Pandaren bringt Gerichte hervor, die Eure körperliche Stärke erhöhen. Bringt einige rohe Tigersteaks zum Meister des Grills und er wird Euch beibringen, was Ihr mit ihnen anstellen könnt. Es gibt viele Tiger im Jadewald und der Krasarangwildnis, aber Ihr könnt sie auch anderswo finden.", sourceObjective = "Bringt 5 rohe Tigersteaks zum Meister des Grills.", progress = "Wenn Ihr den Weg des Grills lernen wollt, bringt mir zunächst ein paar rohe Tigersteaks.", completion = "Exzellente Stücke.", sourceObjectiveStatus = "unverified-source-field" }
quests[31312] = { id = 31312, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die alte Karte", description = "Das alte, verblichene Leder fällt fast auseinander, ist aber immer noch lesbar.\n\nJemand scheint eine Art Karte darauf gezeichnet zu haben... und die folgenden Worte:\n\n\nTief in dem Tal, wo die Vier Winde wehen,\nlacht die Jungfer hinter ihrem güldenen Fächer.\nZu Füßen der Treppe ihrer Ahnen,\nflüstert sie ihr Geheimnis in die hallende Nacht.", sourceObjective = "Zeigt Fischi Rohrroder am Rohrkolbensee oder auf dem Halbhügelmarkt im Tal der Vier Winde die Karte.\n\nBereitgestellter Gegenstand:", completion = "Boah! Ich glaube, Ihr habt sie gefunden, {name}! Ihr habt die Karte zum Schatz des alten Distel gefunden!", sourceObjectiveStatus = "unverified-source-field" }
quests[31313] = { id = 31313, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nur eine Volkserzählung", description = "Was!?! Das ergibt doch überhaupt keinen Sinn! <Fischi macht einen enttäuschten Eindruck.>\n\nWas soll dieses ganze Kauderwelsch von einer Jungfer, einem Ahnen und irgendeiner Treppe?\n\nIch werde daraus einfach nicht schlau... Ihr vielleicht?\n\nNun, es gibt hier eine Menge Leute, die sehr viel älter als Ihr und ich sind, {name}.\n\nKönnt Ihr vielleicht mit den Bewohnern von Halbhügel sprechen? Ich könnte wetten, dass sie etwas wissen!", sourceObjective = "Sprecht mit Korntrenner Pei, Steinmeißler Mac, Mama Min und dem alten Herrn Weißbart.", completion = "Natürlich! Das ergibt absolut Sinn. Der Schatz muss also an der Stelle liegen, wo der See an die Berge angrenzt!", sourceObjectiveStatus = "unverified-source-field" }
quests[31314] = { id = 31314, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Schatz des alten Distel", description = "Na Donnerwetter! Das entwickelt sich ja zu einer waschechten Schatzsuche!\n\nEs muss im Norden eine Art Eingang oder Öffnung geben... an der Stelle, wo die Berge und der Rohrkolbensee zusammentreffen.\n\nWir treffen uns beim Eingang! Dieser Schatz gehört uns!", sourceObjective = "Findet den Höhleneingang und holt Euch den Schatz des alten Distel.", progress = "Wenn ich's nicht mit eigenen Augen sehen würde, wär' es kaum zu glauben!", completion = "Der Deckel der Kiste lässt sich durch einen leichten Schubser herunterschieben. Ihr blickt in die Kiste...", sourceObjectiveStatus = "unverified-source-field" }
quests[31315] = { id = 31315, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Kernlanderbe", description = "Ganz unten in der Schatzkiste findet Ihr einige Schriftrollen und einen weichen Lederbeutel mit Samen.\n\nWenn Ihr die Schriftrollen ausbreitet, seht Ihr darauf detaillierte Notizen zum Landbau, Zeichnungen von Pflanzen, Zahlen und Berechnungen, Positionen nahe gelegener Wasserquellen und einige andere Informationen.\n\nVielleicht interessiert sich ja jemand bei dem Bund der Ackerbauern dafür.", sourceObjective = "Bringt den Almanach des alten Distel zu Saatwärterin Shing Sing in Halbhügel im Tal der Vier Winde.", progress = "Was habt Ihr da?", completion = "Ach ja, ich kenne die Geschichte des alten Distel ziemlich gut, {race}.\n\nÜber seine Schatzsuche gibt es jede Menge verrückte Erzählungen.\n\nTatsächlich war er aber so etwas wie ein Einsiedler... exzentrisch und dabei auch ein hervorragender Bauer.\n\nAn seinem Lebensabend zog er sich in die Berge zurück und ward nie wieder gesehen.\n\nEr war trotz allem einfach nur ein Mann, der sein Leben lebte, und wie es scheint, habt Ihr sein Vermächtnis gefunden.\n\nErzählt Fischi nicht die Wahrheit. Manche der besten Geschichten sind größer als das Leben, von dem sie erzählen.", sourceObjectiveStatus = "unverified-source-field" }
quests[31316] = { id = 31316, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Julia, die Tierzähmerin", description = "Wie ich sehe, habt Ihr Eure Fertigkeiten im Haustierkampf verbessert, {name}. Ich glaube, Ihr seid reif für eine echte Herausforderung.\n\nIhr findet Julia Stevens in den Weinbergen der Maclures, südlich von Sturmwind. Sie ist eine aufstrebende Wildtierzähmerin und ich finde, Ihr solltet Euch mit ihr im Kampf messen!", sourceObjective = "Besiegt Julia Stevens in einem Haustierkampf.", progress = "Wie sieht es mit Eurer Mannschaft aus? Ich habe schon zwei Schlangen!", completion = "Ihr könnt besser mit diesen Tierchen umgehen, als ich dachte!", sourceObjectiveStatus = "unverified-source-field" }
quests[31317] = { id = 31317, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verfolgungsereignis: Eingang gefunden" }
quests[31318] = { id = 31318, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verfolgungsereignis: Schatz gefunden" }
quests[31319] = { id = 31319, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Notfallplan", description = "Eure Kameraden haben sich in unseren Landen eine neue Heimat errichtet und einen gefährlichen Zwist mit sich gebracht.\n\nDas volle Ausmaß der Vernichtung können wir hier noch nicht abschätzen, doch bereits jetzt ist es… unaussprechlich.\n\nUnd doch, Eure Freunde aus Rachegefühlen sich selbst zu überlassen, würde unserer Art zu leben widersprechen. Jeder, der jetzt noch am Leben ist, ist zweifelslos verwundet und bedarf dringend Hilfe.\n\nDieses Feuerwerk war eigentlich dazu gedacht, die Fertigstellung der Statue zu feiern. Benutzt es in der Nähe Eurer Kameraden, um Mishi ein Zeichen zu geben, und sie wird sie in Sicherheit bringen.", sourceObjective = "Benutzt Chos Feuerwerk in der Nähe von Admiral Taylor, Mishka und Sully.", completion = "Mit meinen Gedanken bin ich bei Euren gefallenen Begleitern, Reisender.\n\nMögen ihre Wunden gut heilen.", sourceObjectiveStatus = "unverified-source-field" }
quests[31320] = { id = 31320, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Einen Drink für einen Fisch?", description = "Heeee, Ko...Kollege... Wie läuft's denn so? Wo...wollt Ihr 'nem Ji...inyu nich' was zu trink'n ka...kauf'n?", sourceObjective = "Bringt Jogu dem Betrunkenen 1 Vier-Winde-Soju. Vier-Winde-Soju kann von den meisten Schankkellnern in Pandaria erworben werden.", progress = "Durstig...", completion = "Da...anke, K...Kumpel.", sourceObjectiveStatus = "unverified-source-field" }
quests[31321] = { id = 31321, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine Runde für einen Fisch?", description = "Heyyy, das is' doch mei... <mein Freund/meine Freundin>!\n\nIhr ha...abt mich wohl hier ru...umhäng'n seh'n. Ihr mü...müsst a...aber wiss'n, dass ich nich' be...betrunk'n bin.\n\nIch mein'... se...seht mich doch mal an! Nü...nüchtern wie ein Sü...Süßwasserfisch!\n\nKlar, ich ertränk' meine So...org'n hier u...und da mal in 'nem gu...ut'n Gebräu, a...aber 'nen Jinyu kri...iegt Ihr nich' besoff'n! Kö...Könntet gena...ausogut versuch'n, 'n Fi...isch zu ertränk'n!\n\nNö, vo...von dem Gebr...äu werd' ich immer nur schl...schläfrig. Un' da...ann hab' ich Visio'n von der Zu...ukunft.\n\n\n\nJe stä...ärker das Gebräu, desto stä...ärker meine Träu...Träume! Bringt m...mir was zu schluck'n, un' i...ich schuld' Euch w...was.", sourceObjective = "Bringt Jogu dem Betrunkenen 5 Flaschen Pandarenpflaumenwein. Pandarenpflaumenwein kann von den meisten Schankkellnern in Pandaria erworben werden.", progress = "Was meint Ihr mit \"Ihr lallt wie ein Betrunkener\"? S...So sprech' ich i...immer!", completion = "Oooh, da...das is' gutes Zeug...", sourceObjectiveStatus = "unverified-source-field" }
quests[31322] = { id = 31322, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Fässchen für einen Fisch?", description = "Meine Träu... meine Träume si...ind in letzter Zeit so... fa...arblos, {race}.\n\nIch bra...auch' was Kräftiges, damit ich wieder... a...auf die B...Beine komm'!\n\nIch hab' gehört, e...es gibt da so 'nen le...leckeren Trunk, den die Leu...Leute heutzutage zusamm'nbrau'n.\n\nEs heißt Ja...Jadehex'nbräu.\n\nWürd' ich ge...ern mal... probier'n.", sourceObjective = "Bringt Jogu dem Betrunkenen 10 Flaschen Jadehexenbräu. Jadehexenbräu kann durch Kochkunst hergestellt werden.", progress = "Glück gehabt?", completion = "Oooh, da...das haut ja zi...iemlich rein! Ich we...werd' schon ganz schl...schläfrig...", sourceObjectiveStatus = "unverified-source-field" }
quests[31323] = { id = 31323, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine Brauerei für einen Fisch?", description = "Allso, {name}, damit ich auch in Zu...ukunkft noch Visionen ha...ab'n kann, brauch' ich... meine eig'ne Bra...auerei.\n\n...\n\nIch m...mach doch nur Spaß! Hättet ma...al Euren Gesi... Gesichtsausdruck seh'n soll'n! Einfach he...errlich... hicks!\n\nJed'nfalls hab' ich von n...nem Gebräu gehört, da...as anders sein soll als alle andren. Das... wü...ürd' ich gern mal... probier'n.\n\nHabt Ihr schon vom... Wa...ahnsinnig'n Brauerfrühstück gehört? Wenn... Wenn Ihr mir von de...em Zeug was bringt, sind wir Fr...Freunde fürs Leb'n.", sourceObjective = "Bringt Jogu dem Betrunkenen 20 wahnsinnige Brauerfrühstücke. Wahnsinnige Brauerfrühstücke können durch Kochkunst hergestellt werden.", progress = "Habt Ihr es versucht?", completion = "Danke, {name}! Die we...erd' ich mir fü...ür 'n schlecht'n Ta...ag... zur Seite leg'n... hicks!", sourceObjectiveStatus = "unverified-source-field" }
quests[31324] = { id = 31324, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Familiengeheimnisse", description = "Unsere geheimen Rezepte! Ich habe sie gerade zusammengetragen, doch dann... Ho-zen?\n\n<Tantchen sieht sehr verwirrt aus.>\n\nWie soll Gao so denn etwas zusammenbrauen? Er braucht diese Rezepte, sonst gibt es noch eine Katastrophe!", sourceObjective = "Sammelt 5 Geheimnisse der Sturmbräus.", progress = "Oh, hallo!", completion = "Ho ho, was ist denn das?\n\n<Onkel Gaos fetter Bräubauch schwabbelt beim Anblick der Familienrezepte freudig auf und ab.>\n\nAch, ich wusste doch, dass ich zu viel Mais benutze!", sourceObjectiveStatus = "unverified-source-field" }
quests[31325] = { id = 31325, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine sehr schöne Halskette", description = "Diese wunderschöne Halskette wurde teilweise von den schmutzigen Händen eines Ho-zen verschmiert.\n\nEs gibt im Tal nur eine Person, die ein so schönes Schmuckstück besitzen könnte.", sourceObjective = "Bringt die Halskette zu Tina Lehmkrall in Haohans Haus oder zum Halbhügelmarkt im Tal der Vier Winde.\n\nBereitgestellter Gegenstand:", completion = "Oh, das ist ja meine Lieblingshalskette! Mir war gar nicht bewusst, dass ich sie verloren hatte! Danke, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[31326] = { id = 31326, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tinas elegante Tiara", description = "Es ist eine blendende Diamantentiara. Wer im Tal könnte wohl reich genug sein, um ein solches Schmuckstück zu besitzen?\n\nWer auch immer es ist, er oder sie dürfte eine nette Belohnung herausspringen lassen.", sourceObjective = "Bringt die elegante Tiara zu Tina Lehmkrall in Haohans Haus oder zum Halbhügelmarkt im Tal der Vier Winde.\n\nBereitgestellter Gegenstand:", completion = "Oh, meine Tiara! Ich hatte sie verloren, aber wo um alles in der Welt habt Ihr sie nur gefunden?", sourceObjectiveStatus = "unverified-source-field" }
quests[31327] = { id = 31327, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ärger aus dem Fass", description = "In der Brauerei treiben Ho-zen ihr Unwesen und... wer weiß was noch. Ich bin sicher, dass die Brauer in Schwierigkeiten stecken.\n\nWärt Ihr vielleicht so nett, herauszufinden, was da vor sich geht, <mein Freund/meine Liebe>?", sourceObjective = "Tötet Yan-Zhu den Dekantierten.", completion = "Eine riesige, aus Gebräu entstandene Kreatur?! Wer hätte je gedacht, dass es so etwas geben kann?\n\nDanke, dass Ihr Gao vor seinen eigenen fehlgeleiteten Brauereiexperimenten gerettet habt.", sourceObjectiveStatus = "unverified-source-field" }
quests[31328] = { id = 31328, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein exquisiter Ohrring", description = "Ihr nehmt den Ohrring aus dem pelzigen Ohr der Kreatur. Wie es scheint, hatte der Bursche beim Tragen dieses baumelnden Rings eine Menge Spaß. ZU VIEL Spaß.\n\nVielleicht hätte die Besitzerin dieses anmutigen Schmuckstücks es gern zurück. Ihr müsst ihr ja nicht sagen, wo Ihr es gefunden habt... oder wer es getragen hat.", sourceObjective = "Bringt den exquisiten Ohrring zu Tina Lehmkrall in Haohans Haus oder zum Halbhügelmarkt im Tal der Vier Winde.\n\nBereitgestellter Gegenstand:", completion = "Oh, mein Ohrring! Aber, er passt ja genau zu dem, den ich heute trage!\n\n<Tina steckt sich den Ohrring ins Ohr.>\n\nIch danke Euch, {name}!", sourceObjectiveStatus = "unverified-source-field" }
quests[31329] = { id = 31329, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine wunderschöne Brosche", description = "Diese sehr alte antike Brosche wurde mit viel Liebe zum Detail gefertigt und in einen filigranen Rahmen eingefasst. Sie sieht sehr wertvoll aus.\n\nEs gibt nur eine Person, die immer wieder Schmuckstücke an pelzige Straßendiebe verliert, und sie würde dieses Erbstück vermutlich sehr gerne zurückhaben.", sourceObjective = "Bringt die wunderschöne Brosche zu Tina Lehmkrall in Haohans Haus oder zum Halbhügelmarkt im Tal der Vier Winde.\n\nBereitgestellter Gegenstand:", completion = "Die Brosche meiner Großmutter! Oh, was für ein Glück, dass Ihr sie gefunden habt! Es ist ein wertvolles Familienstück.", sourceObjectiveStatus = "unverified-source-field" }
quests[31331] = { id = 31331, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Anleitung zur Questerstellung", description = "Juchu! Ihr dürft eine Schnitzeljagdquest erstellen! Findet heraus, was als Nächstes zu tun ist.", sourceObjective = "Erstellt eine Schnitzeljagdquest.", sourceObjectiveStatus = "unverified-source-field" }
quests[31332] = { id = 31332, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lektion 1: Pfirsich in Scheiben", description = "Ich brenne schon richtig auf den Beginn meiner Ausbildung. Wir fangen mit einem Pfirsich in Scheiben an, richtig?", sourceObjective = "Besorgt Euch 5 Pandarenpfirsiche für Nomis Kochstunde.", progress = "Ich will so gern Koch werden, die anderen Kinder haben aber schon vor zwei Monaten angefangen. Ohne Eure Hilfe hole ich sie niemals ein.", completion = "Hier, fertig! Und, wie habe ich mich geschlagen?", sourceObjectiveStatus = "unverified-source-field" }
quests[31333] = { id = 31333, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lektion 2: Fertignudeln", description = "Fertignudeln sind ja nicht so schwer zu kochen, oder?", sourceObjective = "Besorgt 5 Portionen Fertignudeln für Nomis Kochlektion.", progress = "Es ist so leicht, die Nudeln zu verkochen!", completion = "Hier, fertig! Und, wie habe ich mich geschlagen?", sourceObjectiveStatus = "unverified-source-field" }
quests[31334] = { id = 31334, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lektion 3: Gerösteter Trockenfisch", description = "Das Kochen ist schwieriger, als ich dachte. Es ist so schnell etwas verbrannt.", sourceObjective = "Besorgt 5 Goldkarpfen für Nomis Kochlektion.", progress = "Hoffentlich verbrenne ich mich nicht. IIH!", completion = "Hier, fertig! Und, wie habe ich mich geschlagen?", sourceObjectiveStatus = "unverified-source-field" }
quests[31335] = { id = 31335, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lektion 4: Getrocknete Nadelpilze", description = "Mit Pilzen hab' ich's nicht so besonders... aber ich werde mein Bestes tun, mehr über sie zu lernen.", sourceObjective = "Besorgt 5 Nadelpilze für Nomis Kochlektion.", progress = "Igitt.", completion = "Hier, fertig! Und, wie habe ich mich geschlagen?", sourceObjectiveStatus = "unverified-source-field" }
quests[31336] = { id = 31336, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lektion 5: Stampfreiskuchen", description = "Ich liebe Reiskuchen. Ich werde mein Bestes tun, ganz besonders gute zu backen!", sourceObjective = "Besorgt Euch 5 Portionen Reis für Nomis Kochlektion.", progress = "Ich bin schon ganz gespannt, ob sie was werden!", completion = "Hier, fertig! Und, wie habe ich mich geschlagen?", sourceObjectiveStatus = "unverified-source-field" }
quests[31337] = { id = 31337, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Zeichen der Anerkennung", description = "Danke, dass Ihr Euch vergewissert habt, dass bei mir alles zum Besten steht! Ich konnte heute der Familie Eisentatz helfen, und man gestattete mir, Euch dies zu überbringen.", sourceObjective = "Nehmt Nomis Geschenk an.", completion = "Ihr seid mein absoluter Lieblingslehrer!", sourceObjectiveStatus = "unverified-source-field" }
quests[31338] = { id = 31338, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein verlorenes Schäfchen", description = "Schäfchen, Chi-Chis wertvollstes Schaf, ist verschwunden!\n\nDas dumme Ding ist immer wieder vom Hof weggelaufen.\n\nDummes Schaf! Ich hab' überall gesucht, konnte es aber nicht finden.\n\nKönnt Ihr mir helfen, {race}?", sourceObjective = "Findet Schäfchen und bringt es zu Chi-Chi zurück.", progress = "Habt Ihr mein Schäfchen gefunden? Ach, und ich hab' mir solche Sorgen gemacht.", completion = "Oh, Ihr habt ihn gefunden! Danke!", sourceObjectiveStatus = "unverified-source-field" }
quests[31339] = { id = 31339, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schäfchen ist schon wieder weg", description = "Dieses dumme Schaf ist schon wieder abgehauen!\n\nKönnt Ihr es noch mal für mich suchen?", sourceObjective = "Findet Schäfchen und bringt ihn zu Chi-Chi zurück.", progress = "Ach, armes Schäfchen. Ist sicher ganz verängstigt und furchtbar allein...", completion = "Schäfchen, ich hab' mir ja solche Sorgen gemacht! Böses Schaf! Chi-Chi war ja so beunruhigt!", sourceObjectiveStatus = "unverified-source-field" }
quests[31340] = { id = 31340, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ach, Schäfchen...", description = "Seufz... Ihr habt es sicher erraten... Schäfchen ist fort... SCHON WIEDER.\n\nDummes Schaf! Macht mir immer so viel Ärger!\n\nIch muss Euch noch einmal um einen Gefallen bitten, aber ist garantiert das letzte Mal, versprochen.\n\nKönnt Ihr für mich nach Schäfchen suchen?", sourceObjective = "Findet Schäfchen.", completion = "Was? Schäfchen ist... fort?\n\n<Chi-Chis Lippen beginnen zu beben.>", sourceObjectiveStatus = "unverified-source-field" }
quests[31341] = { id = 31341, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Wolf im Schafspelz", description = "AAAARRRRRGGGHHHHH!!!! Dieser letzte Tropfen hat das Fass zum Überlaufen gebracht!\n\nDiese dummen Ho-zen auf dem Berg haben mein SCHÄFCHEN umgebracht!\n\nIch weiß genau, wer es war, und diesmal werde ich mich RÄCHEN.\n\nWenn Ihr mir helfen wollt, legt diesen alten Schafspelz an.\n\nVerkleidet Euch damit und wartet irgendwo auf dem Berg im Norden auf diesen kleinen Knatzel Krungko. Wenn er aus seinem Versteck kommt, brecht ihm die Knochen!", sourceObjective = "Benutzt den alten Schafspelz irgendwo auf der Himmelsweite oder in Kunzen und tötet dann Krungko.", completion = "Danke, {name}. Das bringt mein Schäfchen zwar nicht zurück, aber wenigstens werde ich nun keine weiteren Schafe verlieren.", sourceObjectiveStatus = "unverified-source-field" }
quests[31342] = { id = 31342, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Weg zum Respekt liegt in der Gewalt", description = "Ihr habt Euch im Kampf bewiesen.\n\nWenn Ihr uns auch weiterhin unterstützen wollt, hätte ich noch eine Bitte an Euch.\n\nDas Sha der Gewalt erwartet Euch in den versiegelten Kammern. Vernichtet es, wenn Ihr Euch meinen Respekt verdienen wollt.", sourceObjective = "Tötet das Sha der Gewalt.", completion = "Ihr habt das Sha der Gewalt besiegt und das Kloster gerettet - damit habt Ihr Euch meinen Respekt verdient.\n\nVielleicht haben wir Eure Art falsch eingeschätzt, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[31343] = { id = 31343, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Suche nach Kovok" }
quests[31344] = { id = 31344, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking Event: Chee Chee Exalted" }
quests[31345] = { id = 31345, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking Event: Ella Exalted" }
