quests[31353] = { id = 31353, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking Event: Tina Mudclaw Exalted" }
quests[31354] = { id = 31354, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mazus Freigiebigkeit", sourceObjective = "Sprecht mit Meisterangler Ju Lien in Tropfs Wagnis.", completion = "Hallo!\n\nAch, mir geht es gut. Ich habe nach einem Besuch im \"Abfalleimer\" Nächte erlebt, die schlimmer waren.\n\nJetzt seht Euch doch einmal dieses Ding an. Ich sah es aus dem Meeresboden ragen, als ich dort unten war - Jiao hat es wohl freigesetzt, als er um sich geschlagen hat.\n\nIch bin mir nicht ganz sicher, was ich damit anstellen soll, es sieht aber wertvoll aus. Ihr habt uns mehr oder weniger gerettet, deshalb glaube ich, dass wir Euch diesen Fang schulden.", sourceObjectiveStatus = "unverified-source-field" }
quests[31355] = { id = 31355, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wiederherstellung der Reinheit", description = "{class}, werdet Ihr uns helfen?\n\nDie Reinheit des Tempels ist in Gefahr. Just in diesem Moment kämpfen die drei Meister gegen ihre Zweifel an.\n\nBitte, ich flehe Euch an... helft dem weisen Mari, Liu Flammenherz und Lehrensucher Steinschritt in ihrem Kampf gegen das Sha.", sourceObjective = "Helft dem weisen Mari, Liu Flammenherz und Lehrensucher Steinschritt mit ihren Sha-Problemen.", progress = "Bitte, Ihr müsst jenen im Inneren helfen, bevor sie ihren Zweifeln erliegen.", completion = "Das Schicksal von Priesterin Flammenherz und dem weisen Mari stimmen mich zwar traurig, dennoch habt Ihr meinen aufrichtigen Dank.", sourceObjectiveStatus = "unverified-source-field" }
quests[31356] = { id = 31356, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tiefe Zweifel, tiefe Weisheit", description = "Ein altes Sprichwort der Pandaren sagt: \"Aus großen Zweifeln folgt große Weisheit.\"\n\nDas Sha des Zweifels hat sich im Tempel im Jadeherz eingenistet. Es muss vernichtet werden.\n\nIch möchte behaupten, dass Ihr bald sehr viel weiser sein werdet, {class}.", sourceObjective = "Tötet das Sha des Zweifels.", progress = "Das Sha des Zweifels muss vernichtet werden, {name}, oder wir sind alle verloren.", completion = "Ich habe nie an Euch gezweifelt. Komischerweise wirkt Ihr kein bisschen weiser.\n\n<Der Meister zwinkert mit dem Auge.>", sourceObjectiveStatus = "unverified-source-field" }
quests[31357] = { id = 31357, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Relikte der Vier Könige", description = "Die Mogu sind von Neuem erwacht und stellen eine Bedrohung für ganz Pandaria dar. Und sie stehen kurz davor, noch gefährlicher zu werden.\n\nEs gibt vier legendäre Großkönige der Mogu: Zian des endlosen Schattens, Meng der Irre, Qiang der Gnadenlose und Subetai der Schnelle. Vier Artefakte dieser Könige werden unter uns im Gewölbe der Vergangenen Könige unter Verschluss gehalten.\n\nIhr müsst diese Relikte beschaffen, bevor die Mogu sie entdecken und unaufhaltsam werden.", sourceObjective = "Beschafft die Laterne des Zaubererkönigs, die Waage von König Meng dem Irren, Qiangs \"Die Wissenschaft des Krieges\" und den Bogen von Subetai dem Schnellen.", progress = "Wir müssen die Laterne, die Waage, die Schriftrolle und den Bogen sicherstellen, bevor Xin und seine Klans sie entdecken.", completion = "Ich werde ein besseres Versteck für die vier Relikte finden.\n\nPandaria steht in Eurer Schuld, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[31359] = { id = 31359, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Kunchong-Flüsterer", description = "Um eine richtige Verbindung mit Kovok einzugehen, müsst Ihr ihn geistig und körperlich fordern. Respektiert seine Stärke und Intelligenz; nur dann wird er zulassen, dass Ihr ihn ernsthaft ausbildet.\n\nDie Schlickschuppen dienen möglicherweise als angemessene Prüfung seiner Fähigkeiten, und wenn Ihr dabei seid, ist er nicht in Gefahr.\n\nAußerdem können wir damit ihre Reihen im Salzigen Schlick lichten.", sourceObjective = "Tötet das Orakel Zisch'et und 10 Angehörige des Stammes der Schlickschuppen.", completion = "Euer Fortschritt ist höchst beeindruckend, Erwecker. Kovoks Training schreitet gut voran und er scheint Euch zu mögen.\n\nIhr seid zweifelsfrei die beste Wahl, um mir bei seiner Erziehung zu helfen.", sourceObjectiveStatus = "unverified-source-field" }
quests[31360] = { id = 31360, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine neue Lektion für den Meister", description = "Ein neuer König der Mogu ist an der Macht: Xin der Waffenmeister.\n\nHat die Klans der Mogu eigenhändig unterworfen... Deren neue Anführer buhlen nun um seine Gunst.\n\nIch weiß von niemandem, der ihm im Kampf das Wasser reichen könnte. Unterschätzt Xin nicht, {name}.\n\nUnser Schicksal liegt in Euren Händen.", sourceObjective = "Tötet Xin den Waffenmeister.", progress = "Der König der Mogu muss sterben.\n\nEines Tages wird es zwar einen anderen geben, doch er wird nicht so tödlich sein wie Xin der Waffenmeister.", completion = "Eine wahrlich legendäre Schlacht.\n\nIch bin froh, dass Ihr auf unserer Seite seid, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[31362] = { id = 31362, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das letzte Puzzleteil", description = "Ich muss sagen, {name}, trotz der Scharmützel mit den Ho-zen habe ich die Jinyu noch nie so militant erlebt.\n\nDas beunruhigt mich. Allerdings müssen wir das zu einem anderen Zeitpunkt besprechen. Ich bin hier, um Euch um Eure Unterstützung zu bitten.\n\nDas uralte Fresko, dort, wo wir uns zuletzt unterhielten, ist fast enthüllt. Ich bin mir sicher, dass es uralte Weisheit enthält - Weisheit, von der der Kaiser wollte, dass wir sie nicht vergessen.\n\nDurch Meditation allein kann ich ihre Bedeutung vielleicht nicht rechtzeitig enthüllen. Bitte, bringt dieses Erbstück zum Schrein meiner Ahnen. Mit ihrer Hilfe werden wir dieses Rätsel lösen können.", sourceObjective = "Benutzt Chos Erbstück bei Chos Familienschrein beim Schlangenblick.\n\nUm dorthin zu kommen, sprecht mit Mishi.", completion = "<Lehrensucher Cho schüttelt sich unwillkürlich.>\n\nDie Legenden… sie sind wahr!", sourceObjectiveStatus = "unverified-source-field" }
quests[31363] = { id = 31363, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gebt das Signal", description = "Wir brauchen Verstärkung! Jemand muss sich durchkämpfen und die Signalflamme entfachen.\n\nEs hängt alles von Euch ab, {class}. Fühlt Euch jetzt bloß nicht unter Druck gesetzt oder so.", sourceObjective = "Entfacht die Signalflamme.", completion = "Hervorragend, {name}. Ihr hättet es von der Zeit her nicht besser machen können!", sourceObjectiveStatus = "unverified-source-field" }
quests[31364] = { id = 31364, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Was für ein Brocken!", description = "Die Mantis verfügen über etwas, das sie Raigonn nennen. Es ist ein riesiges Insekt, mit dem sie die Tore der Mauer einstoßen!\n\nLasst uns sicherstellen, dass dieses Ding nicht ins Tal gelangt!", sourceObjective = "Tötet Raigonn.", completion = "Hätte ich es nicht mit eigenen Augen gesehen, ich hätte es wohl nicht geglaubt.\n\nGut gemacht, {name}!", sourceObjectiveStatus = "unverified-source-field" }
quests[31365] = { id = 31365, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Irgendwo da drinnen", description = "Ich habe ein Dutzend meiner besten Männer vorausgeschickt, um die Mantisbelagerung zu infiltrieren.\n\nKeiner von ihnen ist bisher zurückgekehrt.\n\nDa Ihr die Mantis direkt angreifen werdet, bietet sich Euch die Chance, alle zu befreien, die das Pech hatten, in Gefangenschaft zu geraten.\n\nWerdet Ihr das für uns tun?", sourceObjective = "Rettet 12 gefangene Shado-Pan.", progress = "Meine Männer werden irgendwo im Bereich der Mantisbelagerung festgehalten.", completion = "Ich sage dreizehnmal danke - zwölfmal für jene, die Ihr gerettet habt, und einmal für mich selbst.\n\nUnd hier ist noch etwas, das ich Euch als Zeichen der Dankbarkeit überreichen möchte.", sourceObjectiveStatus = "unverified-source-field" }
quests[31366] = { id = 31366, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schaltet den Schwadronsführer aus", description = "Die Mantis belagern den Niuzaotempel.\n\nSchwadronsführer Ner'onok und seine Einheit arbeiten in diesem Augenblick daran, die letzte Kluft zu überbrücken.\n\nIhr müsst ihn und seine Leute aufhalten, bevor sie die Brücke wieder aufbauen.", sourceObjective = "Tötet Schwadronsführer Ner'onok.", completion = "Der Schwadronsführer ist tot, die Belagerung zerschlagen.\n\nIhr habt den Tempel gerettet, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[31367] = { id = 31367, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Lehrensucher", description = "Ihr wollt also mehr über dieses Land erfahren?\n\nSehr gut! Dann solltet Ihr mit Lehrensucher Cho im Heim des Wissens sprechen.\n\nIhr findet ihn in dem Raum oberhalb des Eingangs zum Mogu'shanpalast. Sprecht mit Mishi, um dorthin zu gelangen.", sourceObjective = "Sprecht mit Lehrensucher Cho im Heim des Wissens im Tal der Ewigen Blüten.", completion = "Ja, ich kann Euch am Gesicht ansehen, dass Ihr ein Interesse an der Geschichte habt. Dann seid Ihr hier am richtigen Ort.", sourceObjectiveStatus = "unverified-source-field" }
quests[31368] = { id = 31368, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Lehrensucher", description = "Ihr wollt also mehr über dieses Land erfahren?\n\nSehr gut! Dann solltet Ihr mit Lehrensucher Cho im Heim des Wissens sprechen.\n\nIhr findet ihn in dem Raum oberhalb des Eingangs zum Mogu'shanpalast. Sprecht mit Mishi, um dorthin zu gelangen.", sourceObjective = "Sprecht mit Lehrensucher Cho im Heim des Wissens im Tal der Ewigen Blüten.", progress = "Willkommen, Reisender.", completion = "Ja, ich kann Euch am Gesicht ansehen, dass Ihr ein Interesse an der Geschichte habt. Dann seid Ihr hier am richtigen Ort.", sourceObjectiveStatus = "unverified-source-field" }
quests[31369] = { id = 31369, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Angler", description = "Wenn Ihr all die Geheimnisse des tiefen Ozeans erkunden und ein paar richtig große Fische fangen wollt, solltet Ihr mit Haito an der Anlegestelle der Angler in der Krasarangwildnis sprechen.\n\nEr wird Euch sicher gern ein oder zwei Dinge über die Angelei erzählen!", sourceObjective = "Sprecht mit dem Angler Haito an der Anlegestelle der Angler in der Krasarangwildnis.", completion = "Seid Ihr bereit für GROSSE Fische?", sourceObjectiveStatus = "unverified-source-field" }
quests[31370] = { id = 31370, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Angler", description = "Wenn Ihr all die Geheimnisse des tiefen Ozeans erkunden und ein paar richtig große Fische fangen wollt, solltet Ihr mit Haito an der Anlegestelle der Angler in der Krasarangwildnis sprechen.\n\nEr wird Euch sicher gern ein oder zwei Dinge über die Angelei erzählen!", sourceObjective = "Sprecht mit dem Angler Haito an der Anlegestelle der Angler in der Krasarangwildnis.", completion = "Seid Ihr bereit für GROSSE Fische?", sourceObjectiveStatus = "unverified-source-field" }
quests[31371] = { id = 31371, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Trackingereignis: Spieler hat eine tägliche Angelquest abgeschlossen" }
quests[31372] = { id = 31372, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Ackerbauern", description = "Die Ackerbauern gehen ihrem Beruf in Halbhügel im Tal der Vier Winde nach.\n\nWenn Ihr Interesse an ihrer Arbeit habt, solltet Ihr vielleicht mit Bauer Yoon sprechen. Er ist noch neu im Ort.\n\nIch wette, er kann etwas Hilfe gebrauchen.", sourceObjective = "Sprecht mit Bauer Yoon auf dem Gehöft Sonnensang im Tal der Vier Winde.", sourceObjectiveStatus = "unverified-source-field" }
quests[31373] = { id = 31373, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Orden der Wolkenschlange", description = "Der Orden der Wolkenschlange ist immer auf der Suche nach Reittalenten.\n\nWenn Ihr Euch uns anschließen wollt, solltet Ihr mit Ausbilder Himmelsdorn im Arboretum im Jadewald sprechen.\n\nIch wünsche Euch viel Glück, {race}.", sourceObjective = "Sprecht mit Ausbilder Himmelsdorn im Arboretum im Jadewald.", sourceObjectiveStatus = "unverified-source-field" }
quests[31374] = { id = 31374, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Ackerbauern", description = "Die Ackerbauern gehen ihrem Beruf in Halbhügel im Tal der Vier Winde nach.\n\nWenn Ihr Interesse an ihrer Arbeit habt, solltet Ihr vielleicht mit Bauer Yoon sprechen. Er ist noch neu im Ort.\n\nIch wette, er kann etwas Hilfe gebrauchen.", sourceObjective = "Sprecht mit Bauer Yoon auf dem Gehöft Sonnensang im Tal der Vier Winde.", sourceObjectiveStatus = "unverified-source-field" }
quests[31375] = { id = 31375, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Orden der Wolkenschlange", description = "Der Orden der Wolkenschlange ist immer auf der Suche nach Reittalenten.\n\nWenn Ihr Euch uns anschließen wollt, solltet Ihr mit Ausbilder Himmelsdorn im Arboretum im Jadewald sprechen.\n\nIch wünsche Euch viel Glück, {race}.", sourceObjective = "Sprecht mit Ausbilder Himmelsdorn im Arboretum im Jadewald.", sourceObjectiveStatus = "unverified-source-field" }
quests[31376] = { id = 31376, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Angriff auf den Tempel der Jadeschlange", description = "Der Tempel der Jadeschlange wird in Dunkelheit gehüllt und Yu'lons Priester haben uns um Hilfe gebeten.\n\nNoch können sie das Sha in Schach halten, aber nicht mehr lange.\n\nVielleicht gelingt es Euch ja, den Feind zu überwinden, {class}.", sourceObjective = "Sprecht mit dem Ältestenweisen Tai-Feng auf dem Tempelgelände der Jadeschlange im Jadewald.", completion = "Ihr kommt gerade rechtzeitig.", sourceObjectiveStatus = "unverified-source-field" }
quests[31377] = { id = 31377, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Angriff auf den Tempel der Jadeschlange", description = "Der Tempel der Jadeschlange wird in Dunkelheit gehüllt und Yu'lons Priester haben uns um Hilfe gebeten.\n\nNoch können sie das Sha in Schach halten, aber nicht mehr lange.\n\nVielleicht gelingt es Euch ja, den Feind zu überwinden, {class}.", sourceObjective = "Sprecht mit dem Ältestenweisen Tai-Feng auf dem Tempelgelände der Jadeschlange im Jadewald.", completion = "Ihr kommt gerade rechtzeitig.", sourceObjectiveStatus = "unverified-source-field" }
quests[31378] = { id = 31378, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Herausforderung am Tempel des Roten Kranichs", description = "Der Tempel des Roten Kranichs ist nach dem Auftauchen des Sha immer noch in Aufruhr. Erst vor Kurzem konnten sie beginnen, die Truppen zu sammeln und die Übungen für die Krieger wieder aufzunehmen.\n\nWenn Ihr dem Tempel helfen möchtet, dann sprecht mit Thelonius an Chi-Jis Wiege.", sourceObjective = "Sprecht mit Thelonius an Chi-Jis Wiege in der Krasarangwildnis.", completion = "Ich heiße Euch willkommen.", sourceObjectiveStatus = "unverified-source-field" }
quests[31379] = { id = 31379, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Herausforderung am Tempel des Roten Kranichs", description = "Der Tempel des Roten Kranichs ist nach dem Auftauchen des Sha immer noch in Aufruhr. Erst vor Kurzem konnten sie beginnen, die Truppen zu sammeln und die Übungen für die Krieger wieder aufzunehmen.\n\nWenn Ihr dem Tempel helfen möchtet, dann sprecht mit Thelonius an Chi-Jis Wiege.", sourceObjective = "Sprecht mit Thelonius an Chi-Jis Wiege in der Krasarangwildnis.", completion = "Ich heiße Euch willkommen.", sourceObjectiveStatus = "unverified-source-field" }
quests[31380] = { id = 31380, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Herausforderung am Tempel des Weißen Tigers", description = "Xuen, der große Himmlische des Nordes, ist auf der Suche nach den größten Kämpfern des Landes.\n\nHeute wird er seine Herausforderungen am Kun-Lai-Gipfel abhalten.\n\nWenn Ihr Euch mit den stärksten Kämpfern aus ganz Pandaria messen wollt, dann sucht ihn auf und betretet den Ring der Herausforderer!", sourceObjective = "Sprecht mit Xuen am Tempel des Weißen Tigers am Kun-Lai-Gipfel.", completion = "Ihr möchtet also Eure Fähigkeiten auf die Probe stellen? Sehr gut, {race}.", sourceObjectiveStatus = "unverified-source-field" }
quests[31381] = { id = 31381, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Herausforderung am Tempel des Weißen Tigers", description = "Xuen, der große Himmlische des Nordes, ist auf der Suche nach den größten Kämpfern des Landes.\n\nHeute wird er seine Herausforderungen am Kun-Lai-Gipfel abhalten.\n\nWenn Ihr Euch mit den stärksten Kämpfern aus ganz Pandaria messen wollt, dann sucht ihn auf und betretet den Ring der Herausforderer!", sourceObjective = "Sprecht mit Xuen am Tempel des Weißen Tigers am Kun-Lai-Gipfel.", completion = "Ihr möchtet also Eure Fähigkeiten auf die Probe stellen? Sehr gut, {race}.", sourceObjectiveStatus = "unverified-source-field" }
quests[31382] = { id = 31382, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Verteidigung des Niuzaotempels", description = "Der Niuzaotempel im äußersten Westen, wird von den Mantis angegriffen.\n\nBis jetzt konnte der Große Himmlische sie aufhalten, aber auf sich allein gestellt kann selbst er nicht ewig durchhalten.\n\nIhr müsst den Verteidigern helfen, {class}. Der Tempel darf nicht fallen!", sourceObjective = "Sprecht mit Ogo dem Ältesten im Niuzaotempel in der Tonlongsteppe.", completion = "Ich grüße Euch. Wir können Eure Hilfe wirklich gebrauchen.", sourceObjectiveStatus = "unverified-source-field" }
quests[31383] = { id = 31383, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Verteidigung des Niuzaotempels", description = "Der Niuzaotempel im äußersten Westen, wird von den Mantis angegriffen.\n\nBis jetzt konnte der Große Himmlische sie aufhalten, aber auf sich allein gestellt kann selbst er nicht ewig durchhalten.\n\nIhr müsst den Verteidigern helfen, {class}. Der Tempel darf nicht fallen!", sourceObjective = "Sprecht mit Ogo dem Ältesten im Niuzaotempel in der Tonlongsteppe.", completion = "Ich grüße Euch. Wir können Eure Hilfe wirklich gebrauchen.", sourceObjectiveStatus = "unverified-source-field" }
quests[31384] = { id = 31384, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Goldene Lotus", description = "Der Goldene Lotus bewacht das Tal seit Jahrhunderten. Er hat für seine Sicherheit gesorgt und es vor Schaden bewahrt.\n\nDie jüngsten Ereignisse haben fürchterliche Schrecken über unser Tal gebracht, aber die Verbündeten des Goldenen Lotus halten immer noch gegen sie aus und versuchen, den Frieden wiederherzustellen.\n\nWenn Ihr helfen möchtet, stoßt Ihr am besten bei der Garnison der Untergehenden Sonne zu ihnen.", sourceObjective = "Sprecht mit Anji Herbstlicht in der Garnison der Untergehenden Sonne im Tal der Ewigen Blüten.", completion = "Finstere Zeiten, {class}. Wir freuen uns über jedwede Hilfe, die Ihr bieten könnt.", sourceObjectiveStatus = "unverified-source-field" }
quests[31385] = { id = 31385, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Goldene Lotus", description = "Der Goldene Lotus bewacht das Tal seit Jahrhunderten. Er hat für seine Sicherheit gesorgt und es vor Schaden bewahrt.\n\nDie jüngsten Ereignisse haben fürchterliche Schrecken über unser Tal gebracht, aber die Verbündeten des Goldenen Lotus halten immer noch gegen sie aus und versuchen, den Frieden wiederherzustellen.\n\nWenn Ihr helfen möchtet, stoßt Ihr am besten bei der Garnison der Untergehenden Sonne zu ihnen.", sourceObjective = "Sprecht mit Anji Herbstlicht in der Garnison der Untergehenden Sonne im Tal der Ewigen Blüten.", completion = "Finstere Zeiten, {class}. Wir freuen uns über jedwede Hilfe, die Ihr bieten könnt.", sourceObjectiveStatus = "unverified-source-field" }
quests[31386] = { id = 31386, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Shado-Pan-Offensive", description = "Wir Shado-Pan haben unsere Truppen zum ersten Mal seit vielen, vielen Jahren wieder zusammengezogen.\n\nDas Sha des Hasses ist aus seinem Gefängnis jenseits des Schlangenrückens entkommen und es ist unsere heilige Pflicht, es wieder gefangen zu nehmen.\n\nUnsere Krieger sind zwar sehr fähig, aber leider viel zu wenige. Eure Hilfe werden wir also nicht ablehnen, {class}.\n\nWenn Ihr Euch der Offensive anschließen wollt, sprecht mit Taran Zhu in der Tonlongsteppe.", sourceObjective = "Sprecht mit Taran Zhu am Außenposten Longying in der Tonlongsteppe.", completion = "Ich grüße Euch, {race}.", sourceObjectiveStatus = "unverified-source-field" }
quests[31387] = { id = 31387, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Shado-Pan verstehen", description = "Die Shado-Pan gehören zu den ältesten Beschützern Pandarias.\n\nÜber viele Jahre hinweg werden wir in unserem schneebedeckten Kloster hoch auf dem Kun-Lai-Gipfel ausgebildet. Dabei perfektionieren wir die Geheimnisse der Kampfkunst, die uns von unseren Ahnen weitergereicht wurden.\n\nWir mögen nur wenige sein, doch ein einzelner Shado-Pan kann tödlicher sein als hundert gut ausgebildete Soldaten.\n\nSich dem Orden der Shado-Pan anzuschließen ist ein langwieriges und mühsames Unterfangen voller Entbehrungen. Solltet Ihr diesen Pfad beschreiten wollen, müsst Ihr Euch erst als würdig erweisen.\n\nEs gibt hier dringende Aufgaben zu erledigen. Helft dem Goldenen Lotus bei der Verteidigung des Tals.", sourceObjective = "Erlangt beim Goldenen Lotus einen respektvollen Ruf.", sourceObjectiveStatus = "unverified-source-field" }
quests[31388] = { id = 31388, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Shado-Pan-Offensive", description = "Wir Shado-Pan haben unsere Truppen zum ersten Mal seit vielen, vielen Jahren wieder zusammengezogen.\n\nDas Sha des Hasses ist aus seinem Gefängnis jenseits des Schlangenrückens entkommen und es ist unsere heilige Pflicht, es wieder gefangen zu nehmen.\n\nUnsere Krieger sind zwar sehr fähig, aber leider viel zu wenige. Eure Hilfe werden wir also nicht ablehnen, {class}.\n\nWenn Ihr Euch der Offensive anschließen wollt, sprecht mit Taran Zhu in der Tonlongsteppe.", sourceObjective = "Sprecht mit Taran Zhu am Außenposten Longying in der Tonlongsteppe.", completion = "Ich grüße Euch, {race}.", sourceObjectiveStatus = "unverified-source-field" }
quests[31389] = { id = 31389, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Shado-Pan verstehen", description = "Die Shado-Pan gehören zu den ältesten Beschützern Pandarias.\n\nÜber viele Jahre hinweg werden wir in unserem schneebedeckten Kloster hoch auf dem Kun-Lai-Gipfel ausgebildet. Dabei perfektionieren wir die Geheimnisse der Kampfkunst, die uns von unseren Ahnen weitergereicht wurden.\n\nWir mögen nur wenige sein, doch ein einzelner Shado-Pan kann tödlicher sein als hundert gut ausgebildete Soldaten.\n\nSich dem Orden der Shado-Pan anzuschließen ist ein langwieriges und mühsames Unterfangen voller Entbehrungen. Solltet Ihr diesen Pfad beschreiten wollen, müsst Ihr Euch erst als würdig erweisen.\n\nEs gibt hier dringende Aufgaben zu erledigen. Helft dem Goldenen Lotus bei der Verteidigung des Tals.", sourceObjective = "Erlangt beim Goldenen Lotus einen respektvollen Ruf.", sourceObjectiveStatus = "unverified-source-field" }
quests[31390] = { id = 31390, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Klaxxi", description = "Die Existenz der Klaxxi ist nur eine unbestätigte Legende. Sie sollen weit jenseits der Mauer in der Schreckensöde leben.\n\nDieses Gebiet haben nur wenige betreten. Und noch weniger sind je wieder von dort zurückgekehrt, um ihre Eindrücke zu schildern.\n\nWenn Ihr also unbedingt diese... Klaxxi... finden wollt, es gibt da eine kleine Gruppe Shado-Pan, die die Mauer im Südwesten beschützt. Sie können Euch vielleicht mehr erzählen.", sourceObjective = "Sprecht mit Bogenmeisterin Li am Tor der Untergehenden Sonne zwischen dem Tal der Ewigen Blüten und der Schreckensöde.", completion = "Die Schreckensöde ist ein gefährlicher Ort.", sourceObjectiveStatus = "unverified-source-field" }
quests[31391] = { id = 31391, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Klaxxi", description = "Die Existenz der Klaxxi ist nur eine unbestätigte Legende. Sie sollen weit jenseits der Mauer in der Schreckensöde leben.\n\nDieses Gebiet haben nur wenige betreten. Und noch weniger sind je wieder von dort zurückgekehrt, um ihre Eindrücke zu schildern.\n\nWenn Ihr also unbedingt diese... Klaxxi... finden wollt, es gibt da eine kleine Gruppe Shado-Pan, die die Mauer im Südwesten beschützt. Sie können Euch vielleicht mehr erzählen.", sourceObjective = "Sprecht mit Bogenmeisterin Li am Tor der Untergehenden Sonne zwischen dem Tal der Ewigen Blüten und der Schreckensöde.", completion = "Die Schreckensöde ist ein gefährlicher Ort.", sourceObjectiveStatus = "unverified-source-field" }
quests[31392] = { id = 31392, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tempel des Weißen Tigers", description = "Habt ihr die Neuigkeiten vernommen, <Reisender/Reisende>? Einer unserer heiligsten Orte wurde angegriffen, das Tal der Ewigen Blüten!\n\nIn diesem Augenblick ist ein menschlicher Prinz im Tempel des Weißen Tigers, der dafür plädiert, dass Euch und den anderen Völkern von jenseits der Nebel Einlass gewährt wird.\n\nDer Tempel befindet sich im Nordosten des Kun-Lai. Vielleicht könnt Ihr den Weißen Tiger überzeugen, Euch hineinzulassen?\n\nIch kann nur hoffen, dass das Tal nicht vollständig zerstört wurde...", sourceObjective = "Sprecht mit Anduin Wrynn im Tempel des Weißen Tigers am Kun-Lai-Gipfel.", completion = "{class}, ich bin froh, dass Ihr hier seid! In den Überlieferungen der Pandaren gibt es einen legendären Ort, das Tal der Ewigen Blüten. Wenn man den Geschichten der Einheimischen Glauben schenken kann, handelt es sich um einen Ort mit großen heilerischen Kräften.\n\nAber der Kriegshäuptling der Horde hat dem Tal Unsagbares angetan.\n\nWir müssen dort einfach hinein!", sourceObjectiveStatus = "unverified-source-field" }
quests[31393] = { id = 31393, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tempel des Weißen Tigers", description = "Habt ihr die Neuigkeiten vernommen, <Reisender/Reisende>? Einer unserer heiligsten Orte wurde angegriffen, das Tal der Ewigen Blüten!\n\nIn diesem Augenblick ist ein menschlicher Prinz im Tempel des Weißen Tigers, der dafür plädiert, dass Euch und den anderen Völkern von jenseits der Nebel Einlass gewährt wird.\n\nDer Tempel befindet sich im Nordosten des Kun-Lai. Vielleicht könnt Ihr den Weißen Tiger überzeugen, Euch hineinzulassen?\n\nIch kann nur hoffen, dass das Tal nicht vollständig zerstört wurde...", sourceObjective = "Sprecht mit Dezco im Tempel des Weißen Tigers am Kun-Lai-Gipfel.", completion = "Hallo, {class}! Uns wurde eine Audienz beim Weißen Tiger gewährt. Das Tal der Ewigen Blüten wurde unlängst von unserem Kriegshäuptling verheert. Unser Anliegen ist es, dass Horde und Allianz zugleich der Zugang zum Tal gewährt wird, damit die Schäden repariert werden können.\n\nDas Tal ist ein heiliger Ort. Ich glaube, meine Frau Leza sah es in einer Vision – darum ist mein Volk nach Pandaria gekommen. Wir müssen es retten!\n\nMeint Ihr, man wird uns Zugang gewähren?", sourceObjectiveStatus = "unverified-source-field" }
quests[31394] = { id = 31394, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine himmlische Erfahrung", description = "Niemand darf das Tal ohne die Erlaubnis der Himmlischen Erhabenen betreten. Xuen der Weiße Tiger scheint mir Gehör schenken zu wollen.\n\nNach allem, was sich zugetragen hat, sträubt sich Taran Zhu von den Shado-Pan aber dagegen, die Allianz oder die Horde auch nur in die NÄHE des Tals zu lassen.\n\n<Anduin schüttelt den Kopf.>\n\nVielleicht könnt Ihr mir ja helfen, mein Anliegen vorzutragen. Sprecht in unserem Namen mit dem Weißen Tiger. Doch seid vorsichtig! Er könnte Euch eine Reihe von Prüfungen auferlegen...", sourceObjective = "Sprecht mit Xuen und schließt seine Prüfungen ab.", progress = "Seid Ihr mit den Aufgaben des Weißen Tigers fertig?", completion = "Ihr habt es geschafft, {name}!\n\nDer Weiße Tiger hat uns erlaubt, die Pandaren in das Tal der Ewigen Blüten zu begleiten. Ein Außenposten der Allianz wurde dort bereits errichtet. Nun kann der langwierige Wiederaufbau beginnen!", sourceObjectiveStatus = "unverified-source-field" }
quests[31395] = { id = 31395, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine himmlische Erfahrung", description = "Das menschliche Kalb tritt für uns ein. Er ist sehr wortgewandt. Ich kann sehen, warum Baine Bluthuf den Prinzen so sehr schätzt.\n\nDennoch kann ich dieses Argument nicht gelten lassen. Ich bin nicht von Bedeutung, Ihr hingegen seid <ein Held/eine Heldin> der Horde. Vielleicht könntet Ihr ja zu unseren Gunsten vermitteln?\n\nSprecht mit dem Weißen Tiger und tretet für unsere Sache ein, {race}.\n\nSeid vorsichtig! Er könnte Euch eine Reihe von Prüfungen auferlegen...", sourceObjective = "Sprecht mit Xuen und besteht seine Prüfungen.", progress = "Habt Ihr die Prüfungen des Weißen Tigers bestanden, {race}?", completion = "Ihr habt es geschafft, {name}!\n\nDer Weiße Tiger hat uns erlaubt, die Pandaren in das Tal der Ewigen Blüten zu begleiten.\n\nEin Held der Horde hat geschafft, woran der Prinz der Allianz gescheitert ist.\n\nEs befindet sich bereits ein Außenposten der Horde im Tal. Nun müssen wir hart mitanpacken, um die verursachten Schäden zu reparieren!", sourceObjectiveStatus = "unverified-source-field" }
quests[31396] = { id = 31396, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "FLAG - Ship's Storage" }
quests[31397] = { id = 31397, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "FLAG - Wodin's Mantid Shanker" }
quests[31398] = { id = 31398, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auseinanderfallen", description = "Warum haben die Saurok Bern? Und noch viel wichtiger: Warum bewacht das Orakel Zish'et ihn so eifersüchtig?\n\nDass er aus dem schwer bewachten Zan'vess stammt, ist unwahrscheinlich - woher kommt er also?\n\nVielleicht wissen die Klaxxi, was wir davon halten sollen.", sourceObjective = "Bringt Kaz'tik dem Manipulator den leuchtenden Bern zurück.", progress = "Wo habt Ihr das gefunden?", completion = "Es war klug von Euch, uns das zu bringen. Das ist ein Stück Bern, das einen anderen Getreuen umhüllt hat.\n\nDer Schaden deutet darauf hin, dass der Getreue in Schwierigkeiten stecken könnte.\n\nIch werde mit dem Rat sprechen, um eine Entscheidung zu treffen, was als Nächstes geschehen soll.", sourceObjectiveStatus = "unverified-source-field" }
quests[31399] = { id = 31399, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "FLAG - Ancient Pandaren Mining Pick" }
