quests[31438] = { id = 31438, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "FLAG - Hammer of the Poisoned Mind" }
quests[31439] = { id = 31439, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verlorenes Signal", description = "Jemand scheint sich am Signalfeuer in der Bernscheinkuhle zu schaffen gemacht zu haben. Kurz bevor es ausfiel, empfingen die Klaxxi'va ein Signal von einem anderen Getreuen in der Nähe.\n\nSie glauben, er versteckt sich in diesem elenden kleinen Sumpf, dem Dämmerwurzmoor.\n\nIch werde Euch im Moor treffen, um ein Behelfssignal aufzustellen, bis ich die Bernscheinkuhle wieder zum Laufen bringe.\n\nIhr werdet den Getreuen erwecken und dann werdet Ihr mir helfen.", sourceObjective = "Erweckt den Getreuen im Dämmerwurzmoor.", completion = "Wie es scheint, fängt meine Arbeit gleich an. Ihr seid an einen gefährlichen Ort gekommen, Erwecker.", sourceObjectiveStatus = "unverified-source-field" }
quests[31440] = { id = 31440, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die vier Folianten", description = "In Scholomance gibt es vier große Folianten mit mächtigem nekromantischem Wissen: \"Im Schatten des Lichts\", \"Kel'Thuzads tiefgründiges Wissen\", \"Verbotene Riten und andere nekromantische Rituale\" und \"Der dunkle Zauberfoliant\".\n\nWährend wir uns unseren Weg durch diesen verfluchten Ort bahnen, müsst Ihr jedes dieser Bücher finden und vernichten. Wir müssen verhindern, dass sich auch nur ein weiterer Dummkopf ihre teuflischen Geheimnisse zu eigen macht.", sourceObjective = "Vernichtet die vier Folianten: \"Im Schatten des Lichts\", \"Kel'Thuzads tiefgründiges Wissen\", \"Verbotene Riten und andere nekromantische Rituale\" und \"Der dunkle Zauberfoliant\".", progress = "Die Geheimnisse der vier Folianten haben diesen Ort und alle, die mit ihm in Verbindung stehen, zu ewigem Leiden verdammt.\n\nSie müssen zerstört werden!", completion = "Danke, {name}.\n\nDa die Folianten nun zerstört sind, kann ich meine ewige Ruhe in dem Wissen antreten, dass diese Bücher niemals wieder einer lebenden Seele schaden werden.", sourceObjectiveStatus = "unverified-source-field" }
quests[31441] = { id = 31441, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Korruption auf allen Ebenen", description = "Heute lernt Ihr, dass man zu Kriegszeiten niemandem vertrauen kann, <Erwecker/Erweckerin>. Selbst diejenigen, die den Klaxxi am nächsten stehen, sind anfällig für Korruption.\n\nWer weiß, seit wann dieser Verräter schon verdorben ist. Er muss vernichtet werden!\n\nIhr seht verwirrt aus. Seht Ihr den Verräter in unseren Reihen denn nicht? Erlaubt mir, Euren Blick zu korrigieren.", sourceObjective = "Bezwingt den Verräter im Dämmerwurzmoor.", completion = "Davon werdet Ihr mehr zu sehen bekommen. Der Krieg ist niemals ein hübscher Anblick.\n\nDie Verderbtheit der Kaiserin reicht weit und ist nur schwer zu entdecken.\n\nEs gibt viel zu tun. Wir müssen anfangen, den Schaden, den Kor'ik angerichtet hat, wiedergutzumachen.", sourceObjectiveStatus = "unverified-source-field" }
quests[31442] = { id = 31442, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die vier Folianten", description = "In Scholomance gibt es vier große Folianten mit mächtigem nekromantischem Wissen: \"Im Schatten des Lichts\", \"Kel'Thuzads tiefgründiges Wissen\", \"Verbotene Riten und andere nekromantische Rituale\" und \"Der dunkle Zauberfoliant\".\n\nWährend wir uns unseren Weg durch diesen verfluchten Ort bahnen, müsst Ihr jedes dieser Bücher finden und vernichten. Wir müssen verhindern, dass sich auch nur ein weiterer Dummkopf ihre teuflischen Geheimnisse zu eigen macht.", sourceObjective = "Vernichtet die vier Folianten: \"Im Schatten des Lichts\", \"Kel'Thuzads tiefgründiges Wissen\", \"Verbotene Riten und andere nekromantische Rituale\" und \"Der dunkle Zauberfoliant\".", progress = "Die Geheimnisse der vier Folianten haben diesen Ort und alle, die mit ihm in Verbindung stehen, zu ewigem Leiden verdammt.\n\nSie müssen zerstört werden!", completion = "Danke, {name}.\n\nDa die Folianten nun zerstört sind, kann ich meine ewige Ruhe in dem Wissen antreten, dass diese Bücher niemals wieder einer lebenden Seele schaden werden.", sourceObjectiveStatus = "unverified-source-field" }
quests[31443] = { id = 31443, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fliegender Tigergurami", description = "Ihr habt einen einzigartigen Fisch gefangen... mit Flügeln. Vielleicht solltet Ihr Nat Pagle bei der Anlegestelle der Angler nach seiner Expertenmeinung fragen.", sourceObjective = "Bringt den fliegenden Tigergurami zu Nat Pagle an der Anlegestelle der Angler.", progress = "Fliegende Fische?", completion = "Ist das ein fliegender Tigergurami?\n\nBei diesem kleinen Fisch handelt es sich um eine seltene Mutation von Tigergurami, die des Fliegens mächtig sind und daher im Süßwasser von Pandaria gefangen werden können.\n\nDen hiesigen Legenden zufolge soll der Person, die diesen Fisch verzehrt, das Glück hold sein. Und die örtliche Tradition gebietet, dass nur der Adel ihn verzehren darf. Wer diese \"Tradition\" verletzt, unterschreibt damit sein eigenes Todesurteil.\n\nIch werde folglich dafür sorgen, dass der Fisch den richtigen Abnehmer findet.", sourceObjectiveStatus = "unverified-source-field" }
quests[31444] = { id = 31444, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stachelfischalpha", description = "Ihr habt etwas ganz Besonderes gefangen... und es sieht ziemlich aggressiv aus.\n\nVielleicht weiß Nat Pagle an der Anlegestelle der Angler mehr darüber?", sourceObjective = "Bringt den Stachelfischalpha zu Nat Pagle an der Anlegestelle der Angler.", progress = "Merkwürdige Fische?", completion = "Das ist doch nicht etwa das, wofür ich es halte, oder? Oh Mann, ein Stachelfischalpha, eines der tödlichsten Raubtiere Pandarias.\n\nStachelfische sind verformte Monstrositäten, die durch die Gegenwart eines Sha entstanden. Die größten Exemplare sind einfach furchterregend. Die Alphatiere verschlingen oft die anderen Stachelfische, obwohl an ihnen absolut nichts Essbares ist.\n\nZu unser beider Glück sind sie für Alchemisten hochinteressant.", sourceObjectiveStatus = "unverified-source-field" }
quests[31445] = { id = 31445, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "zzOld", description = "Wenn Ihr all die Geheimnisse der Tiefsee erforschen und einige große Fische fangen wollt, sprecht mit meinem Bruder Haito an der Anglegestelle der Angler in der Krasarangwildnis.\n\nIch bin mir sicher, dass er Euch gern die eine oder andere Sache über die Angelkunst beibringt.", sourceObjective = "Sprecht mit Angler Haito an der Anlegestelle der Angler in der Krasarangwildnis.", sourceObjectiveStatus = "unverified-source-field" }
quests[31446] = { id = 31446, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fintenfisch", description = "Ihr wisst nicht genau wie, aber Ihr habt einen außergewöhnlichen Kopffüßler gefangen. Nat Pagle an der Anlegestelle der Angler dürfte sich sehr dafür interessieren.", sourceObjective = "Bringt den Fintenfisch zu Nat Pagle an der Anlegestelle der Angler.", progress = "Sich tarnende Tintenfische?", completion = "Ist das ein Fintenfisch? Einer meiner Kumpels hat vor einigen Jahren mal einen vor der Küste von Zandalar gefangen. Hätte es fast nicht lebend zurück geschafft. Lästige Trolle dort, aber schöne Gegend zum Angeln!\n\nJedenfalls sind die Tierchen nicht so selten, wie Ihr vielleicht meint. Sie tarnen sich, um sich unter Steinen und Pflanzen zu verstecken. Nur die besten Angler können sich Chancen ausrechnen, diesen scheuen, aber unglaublich gut schmeckenden Leckerbissen zu fangen.", sourceObjectiveStatus = "unverified-source-field" }
quests[31447] = { id = 31447, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dem Leiden ein Ende", sourceObjective = "Tötet Dunkelmeister Gandling.", completion = "Erblickt meine wahre Gestalt.\n\nIch stehe tief in Eurer Schuld, werde sie aber niemals begleichen können. Doch ich danke Euch, dass Ihr meine Familie von diesem Fluch befreit habt.\n\nKel'Thuzad, der Lichkönig, und nun auch Dunkelmeister Gandling - sie alle sind tot.\n\nVielleicht finde ja nun auch ich eine Art von Frieden.", sourceObjectiveStatus = "unverified-source-field" }
quests[31448] = { id = 31448, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dem Leiden ein Ende", sourceObjective = "Tötet Dunkelmeister Gandling.", completion = "Erblickt meine wahre Gestalt.\n\nIch stehe tief in Eurer Schuld, werde sie aber niemals begleichen können. Doch ich danke Euch, dass Ihr meine Familie von diesem Fluch befreit habt.\n\nKel'Thuzad, der Lichkönig, und nun auch Dunkelmeister Gandling - sie alle sind tot.\n\nVielleicht finde ja nun auch ich eine Art von Frieden.", sourceObjectiveStatus = "unverified-source-field" }
quests[31450] = { id = 31450, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein neues Schicksal", description = "Diese neuen Verbündeten haben uns Aufschluss über eine große und wichtige Wahrheit gegeben: Nicht nur Shen-zin Su geht es schlecht, sondern dem ganzen Land jenseits der Wolken. Die Welt muss geheilt werden, und ich glaube, dass Ihr ihre Heiler sein solltet.\n\nIch möchte, dass Ihr, Ji und Aysa aufbrecht, um Eure Stärke und Weisheit in die Welt zu tragen. Die Allianz und die Horde mögen verschiedene Ideale haben, doch tief in ihrem Inneren verfolgen sie beide edle Absichten.\n\nIhr sollt selbst entscheiden, wer Euch begleiten wird.", sourceObjective = "Sprecht mit dem Geist von Meister Shang Xi und entscheidet Euch dann, ob Ihr mit der Allianz oder der Horde losziehen wollt.", completion = "Und so soll es sein... Hier stehen wir nun in unserem neuen Zuhause.", sourceObjectiveStatus = "unverified-source-field" }
quests[31451] = { id = 31451, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der vermisste Händler", description = "Normalerweise kommt Händler Shi zum Kun-Lai-Gipfel, um mit den Jinyu und Grummel Geschäfte zu machen. Wir haben gehört, dass er nicht in Binan gewesen sein soll, und wir haben ihn auch hier nicht gesehen...\n\nIch mache mir Sorgen... vielleicht ist ihm ja etwas zugestoßen. Könntet Ihr am Tintenkiemenweiher nachsehen? Möglicherweise ist er ja dort.", sourceObjective = "Sprecht mit Händler Shi am Tintenkiemenweiher am Kun-Lai-Gipfel.", completion = "Mein Sohn! Sie haben mir meinen Sohn genommen... Könnt Ihr mir helfen?", sourceObjectiveStatus = "unverified-source-field" }
quests[31452] = { id = 31452, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der vermisste Händler", description = "Normalerweise kommt Händler Shi zum Kun-Lai-Gipfel, um mit den Jinyu und Grummel Geschäfte zu machen. Wir haben gehört, dass er nicht in Binan gewesen sein soll, und wir haben ihn auch hier nicht gesehen...\n\nIch mache mir Sorgen... vielleicht ist ihm ja etwas zugestoßen. Könntet Ihr am Tintenkiemenweiher nachsehen? Möglicherweise ist er ja dort.", sourceObjective = "Sprecht mit Händler Shi am Tintenkiemenweiher am Kun-Lai-Gipfel.", completion = "Mein Sohn! Sie haben mir meinen Sohn genommen... Könnt Ihr mir helfen?", sourceObjectiveStatus = "unverified-source-field" }
quests[31453] = { id = 31453, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Shado-Pan", description = "Unsere neuen Rekruten haben im Stillen über eine Gruppe Pandaren gesprochen, die sie als \"Shado-Pan\" bezeichnen. Allem Anschein nach sind sie sehr stark und geheimnisvoll.\n\nWas auch immer hier am Kun-Lai geschieht, eines steht fest: Um unsere Stellung in Pandaria zu festigen, sind wir auf ein Bündnis mit diesen Shado-Pan angewiesen.\n\nUnd genau da kommt Ihr ins Spiel. Gerüchten zufolge haben sie im Südosten eine Basis... in der Nähe von Feuerzweigwinkel.\n\nBegebt Euch dorthin und schmiert ihnen ordentlich Honig um den Bart. Für die Horde!", sourceObjective = "Sprecht mit Shado-Meister Chong am Shado-Pan-Rückzug in Feuerzweigwinkel.", completion = "Wer seid Ihr? Könnt Ihr kämpfen? Sollte dem so sein, könnten wir Eure Hilfe gebrauchen.", sourceObjectiveStatus = "unverified-source-field" }
quests[31454] = { id = 31454, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine Legende im Werden", description = "Unsere Welt steht am Scheideweg. Die nächsten paar Monate werden die Weichen für die Zukunft stellen - sollte es für uns überhaupt noch eine Zukunft geben.\n\nAch, ich greife schon wieder zu weit vor. Ich sollte wohl einen Gang zurückschalten. Kommt, trinkt mit mir. Lasst uns über die Zukunft von Azeroth sprechen.", sourceObjective = "Lasst Euch von Furorion einen ausgeben und trinkt mit ihm.", sourceObjectiveStatus = "unverified-source-field" }
quests[31455] = { id = 31455, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Shado-Pan", description = "Unsere neuen Rekruten haben im Stillen über eine Gruppe Pandaren gesprochen, die sie als \"Shado-Pan\" bezeichnen. Allem Anschein nach sind sie sehr stark und geheimnisvoll.\n\nUnd genau da kommt Ihr ins Spiel. Gerüchten zufolge haben sie im Südosten eine Basis... in der Nähe von Feuerzweigwinkel. Reist als <Gesandter/Gesandte> der Allianz dorthin und bietet ihnen alle nur erdenkliche Unterstützung an.", sourceObjective = "Sprecht mit Shado-Meister Chong am Shado-Pan-Rückzug in Feuerzweigwinkel.", completion = "Wer seid Ihr? Könnt Ihr kämpfen? Sollte dem so sein, könnten wir Eure Hilfe gebrauchen.", sourceObjectiveStatus = "unverified-source-field" }
quests[31456] = { id = 31456, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gehöft Moschuspranke", description = "Es gibt hier draußen noch eine weitere Siedlung der Pandaren, das Gehöft Moschuspranke. Leider weiß ich nicht, ob es ihnen gut geht - die Yaungolinvasion hat uns alle ziemlich auf Trab gehalten.\n\nIhr wart uns schon eine so große Hilfe... vielleicht könntet Ihr ja nach ihnen sehen, <mein Freund/meine Liebe>?", sourceObjective = "Reist zum Gehöft Moschuspranke am Kun-Lai-Gipfel und sprecht dort mit Lao Moschuspranke.", completion = "Was? Wer zum Henker seid Ihr? Was wollt Ihr hier?\n\nAch, Ihr wollt helfen?", sourceObjectiveStatus = "unverified-source-field" }
quests[31457] = { id = 31457, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gehöft Moschuspranke", description = "Es gibt hier draußen noch eine weitere Siedlung der Pandaren, das Gehöft Moschuspranke. Leider weiß ich nicht, ob es ihnen gut geht - die Yaungolinvasion hat uns alle ziemlich auf Trab gehalten.\n\nIhr wart uns schon eine so große Hilfe... vielleicht könntet Ihr ja nach ihnen sehen, <mein Freund/meine Liebe>?", sourceObjective = "Reist zum Gehöft Moschuspranke am Kun-Lai-Gipfel und sprecht dort mit Lao Moschuspranke.", completion = "Was? Wer zum Henker seid Ihr? Was wollt Ihr hier?\n\nAch, Ihr wollt helfen?", sourceObjectiveStatus = "unverified-source-field" }
quests[31458] = { id = 31458, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schadenskontrolle", description = "Kor'ik sendet seit Wochen Signale an die Kaiserin. Sie weiß über sämtliche Bewegungen der Klaxxi Bescheid.\n\nDas muss jetzt aufhören!\n\nKypari Ik wird als Erstes von Kor'iks Ableben erfahren. Es wäre von Vorteil für uns, wenn wir dafür sorgen könnten, dass diese Nachricht die Kaiserin nicht erreicht.\n\nDie Zerstörung der Flüsterer und des Signals dort wird uns genügend Zeit verschaffen, um einen Plan zu schmieden, ehe die Kaiserin reagieren kann.", sourceObjective = "Vernichtet 5 Flüsterer der Ik'thik und deaktiviert das Signalfeuer von Kypari Ik.", progress = "Informationen bergen Macht, Erwecker. Wer über die meisten Informationen verfügt, hat auch die meiste Macht.", completion = "Ausgezeichnete Arbeit, Erwecker! Das sollte uns die Zeit verschaffen, um den von Kor'ik angerichteten Schaden zu reparieren.\n\nDamit habt Ihr vielleicht das Blatt zu unserem Vorteil gewendet.", sourceObjectiveStatus = "unverified-source-field" }
quests[31459] = { id = 31459, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Chos Schreiben", description = "Einer der Grummel kam vorbei und sagte, Lehrensucher Cho habe nach Euch geschickt. Ihr solltet Euch mit ihm treffen, vielleicht hat er Euch ja etwas Wichtiges zu sagen.\n\nDer Grummel sagte, er sei in Einfass, Richtung Norden.", sourceObjective = "Sprecht mit Lehrensucher Cho in Einfass am Kun-Lai-Gipfel.", completion = "Oh, hallo. Schön, Euch wiederzusehen.", sourceObjectiveStatus = "unverified-source-field" }
quests[31460] = { id = 31460, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Chos Schreiben", description = "Einer dieser putzigen kleinen Grummel kam vorbei und sagte, Lehrensucher Cho habe nach Euch geschickt. Ihr solltet Euch mit ihm treffen!\n\nDer Grummel sagte, er sei in Einfass, Richtung Norden.", sourceObjective = "Sprecht mit Lehrensucher Cho in Einfass am Kun-Lai-Gipfel.", completion = "Oh, hallo. Schön, Euch wiederzusehen.", sourceObjectiveStatus = "unverified-source-field" }
quests[31461] = { id = 31461, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mit Xuen gesprochen" }
quests[31462] = { id = 31462, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Geist der Gewalt besiegt" }
quests[31463] = { id = 31463, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Geist des Zorns besiegt" }
quests[31464] = { id = 31464, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gegnerischer Fraktionsanführer besiegt" }
quests[31465] = { id = 31465, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Antworten entlocken", description = "Kypari Ik ist einer von vielen Orten, an denen der Nachwuchs von Kaiserin Shek'zeer untergebracht ist. Die Jungen sind von Geburt an waghalsig und schwer zu kontrollieren. Außerdem sind sie tödlich.\n\nSchwarmlinge kommen mit einem hochtoxischen Gift zur Welt, dessen Stärke sich mit zunehmendem Alter verringert. Das Gift setzt selbst den stärksten und fähigsten Kämpfer außer Gefecht, wenn es mit seinem Fleisch in Berührung gerät.\n\nIch möchte, dass Ihr mir etwas von diesem Gift bringt.", sourceObjective = "Sammelt 6 mit Gift überzogene Mandibeln von Schwarmlingen der Ik'thik in Kypari Ik.", progress = "Schwarmlinggift verschafft uns nicht nur eine zusätzliche Waffe, sondern wird uns auch helfen, herauszufinden, in welcher Phase sich der Schwarm befindet.", completion = "Dieses Gift befindet sich in einer fortgeschrittenen Phase, jedoch scheint es seine Wirkung nicht zu verlieren...\n\nSehr merkwürdig. Die Klaxxi wollen das bestimmt sofort erfahren. Danke, Erwecker.", sourceObjectiveStatus = "unverified-source-field" }
quests[31466] = { id = 31466, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "FLAG - Took Loot" }
quests[31467] = { id = 31467, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stark wie ein Tiger", description = "Mit dem Grill könnt Ihr diese rohen Tigersteaks zu Nahrung verarbeiten, die Euch stärker macht. Lasst Euch von mir das Rezept für gegrillte Tigersteaks beibringen. Zeigt mir, was Ihr draufhabt.", sourceObjective = "Erlernt das Rezept für gegrillte Tigersteaks vom Meister des Grills und bereitet dann 5 gegrillte Tigersteaks für ihn zu.", progress = "Erlernt das Rezept von mir und zeigt mir dann, was Ihr gelernt habt.", completion = "Stärke und Gesundheit! Sie verkörpern die Wege des Grills.", sourceObjectiveStatus = "unverified-source-field" }
quests[31468] = { id = 31468, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Prüfung des Schwarzen Prinzen", description = "Ich weiß aus verlässlicher Quelle, dass Ihr ein Champion unter den Champions seid, doch würde ich mich gerne selbst von Eurem Können überzeugen - wenn Ihr es gestattet.\n\nDie Mogu, die das Tal der Ewigen Blüten angegriffen haben, die Mogudiener, die in Shan'ze Dao leben, und die vom Sha verderbten Mantis, die die Schreckensöde durchstreifen... sie alle sollten eine angemessene Herausforderung für jemanden Eures Kalibers darstellen.\n\nUnd nun beweist es mir. Aber keine Eile - diese Aufgabe sollte einige Zeit in Anspruch nehmen.", sourceObjective = "Verdient Euch beim Schwarzen Prinzen einen wohlwollenden Ruf. Mogu und Mantis der Stufe 90 im Tal der Ewigen Blüten, der Tonlongsteppe und der Schreckensöde erhöhen Euren Ruf.", sourceObjectiveStatus = "unverified-source-field" }
quests[31470] = { id = 31470, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Weg des Woks", description = "Wenn Ihr Gerichte zubereiten wollt, die Eure Beweglichkeit steigern, solltet Ihr der Meisterin des Woks einige Karotten und Reis bringen. Die Shed-Ling in der Gegend tragen normalerweise viele Karotten mit sich. Wenn Ihr einen Hof habt, könnt Ihr sie auch selbst anbauen.", sourceObjective = "Bringt 5 saftigleckere Karotten zur Meisterin des Woks.", progress = "Hallo, junger Koch. Ihr wollt den Weg des Woks lernen?", completion = "Gut gemacht.", sourceObjectiveStatus = "unverified-source-field" }
quests[31471] = { id = 31471, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Flink wie ein Tiger", description = "Mit dem Wok zu kochen erfordert einiges Geschick. In Eurer ersten Lektion geht es um gebratene Karotten.", sourceObjective = "Erlernt das Rezept für gebratene Karotten von der Meisterin des Woks und bereitet dann 5 Portionen für sie zu.", progress = "Lasst mich Euch beibringen, wie man gebratene Karotten zubereitet.", completion = "Gute Arbeit.", sourceObjectiveStatus = "unverified-source-field" }
quests[31472] = { id = 31472, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Weg des Topfes", description = "Die Küche des Wegs des Topfes hilft Euch, Euren Verstand zu schärfen und somit Eure Intelligenz zu erhöhen. Bringt der Meisterin des Topfes einige Jadelungenfische und sie wird Euch unterweisen. Jadelungenfische könnt Ihr im Jadewald angeln.", sourceObjective = "Bringt 5 Jadelungenfische zur Meisterin des Topfes.", progress = "Ihr wollt das Rezept für verwirbelte Nebelsuppe lernen? Dann bringt mir einige Jadelungenfische.", completion = "Sehr gut. Jetzt lasst uns mit Eurer Lektion beginnen.", sourceObjectiveStatus = "unverified-source-field" }
quests[31473] = { id = 31473, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Stärke Eures Gegners", description = "Große Anführer haben die Macht, das Schicksal ihres Volkes zu lenken, und die Weisheit, die richtigen Entscheidungen zu treffen. Pandaria verfügt über große Macht und uralte Weisheit, doch leider findet man beide nur selten am selben Ort.\n\nWollen wir mal sehen, ob Ihr und ich daran etwas ändern können!\n\nSammelt Siegel der Macht und der Weisheit von den gefallenen Helden im Mogu'shangewölbe, im Herzen der Angst oder der Terrasse des Endlosen Frühlings. Wir werden sie sinnvoller einsetzen können als ihre gegenwärtigen Besitzer.", sourceObjective = "Sammelt 10 Siegel der Macht und 10 Siegel der Weisheit von Schlachtzugsbossen im Mogu'shangewölbe, im Herzen der Angst oder auf der Terrasse des Endlosen Frühlings.", sourceObjectiveStatus = "unverified-source-field" }
quests[31474] = { id = 31474, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Suppe des Nachsinnens", description = "Während man auf den Kochtopf aufpasst, hat man sehr viel Zeit zum Nachdenken. Lasst mich Euch zeigen, wie man verwirbelte Nebelsuppe zubereitet, und Ihr werdet verstehen, was ich meine.", sourceObjective = "Erlernt das Rezept für verwirbelte Nebelsuppe vom Meister des Topfes und bereitet dann 5 Portionen Nebelsuppe für ihn zu.", progress = "Um den Weg des Topfes zu erlernen, müsst Ihr mit verwirbelter Nebelsuppe beginnen.", completion = "Die Intelligenz ist eine Gabe, die Ihr ein Leben lang verfeinern müsst.", sourceObjectiveStatus = "unverified-source-field" }
quests[31475] = { id = 31475, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Weg des Dämpfens", description = "Eine feine Mahlzeit kann Eure Moral heben und Eure Willenskraft stärken, und das gilt ganz besonders für Gerichte, die nach dem Weg des Dämpfens zubereitet wurden. Bringt dem Meister des Dämpfens einige riesige Mantisgarnelen und er wird Euch unterweisen. Riesige Mantisgarnelen könnt Ihr im Meer angeln.", sourceObjective = "Bringt 5 riesige Mantisgarnelen zum Meister des Dämpfens.", progress = "Wenn Ihr den Weg des Dämpfens lernen wollt, braucht Ihr ein paar Shrimps.", completion = "Ausgezeichnete Zutaten.", sourceObjectiveStatus = "unverified-source-field" }
quests[31476] = { id = 31476, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kochen mit Liebe", description = "Wenn ich mit Dampf koche, geht meine ganze kulinarische Liebe in mein Essen über. Lasst mich Euch beibringen, wie man Garnelenklößchen zubereitet.", sourceObjective = "Erlernt das Rezept für Garnelenklößchen vom Meister des Dämpfens und bereitet dann 5 Garnelenklößchen für ihn zu.", progress = "Lasst mich Euch beibringen, wie man Garnelenklößchen zubereitet.", completion = "Gutes Essen bessert die Laune.", sourceObjectiveStatus = "unverified-source-field" }
quests[31477] = { id = 31477, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Durchhaltevermögen", description = "Es heißt, der vom Kranich ernannte Späher stünde bei seinem Schwarm mit einem Stein im Schnabel Wache. Sollte der Späher einschlafen, fällt der Stein herunter, und er wacht wieder auf. Der kunstvolle Umgang mit dem Ofen erfordert Durchhaltevermögen und Geduld. Lernt das Rezept für Wildgeflügelbraten und zeigt mir, dass Ihr das versteht.", sourceObjective = "Erlernt das Rezept für Wildgeflügelbraten von der Meisterin des Ofens und bereitet dann 5 Wildgeflügelbraten für sie zu.", progress = "Lasst Euch von mir das Rezept für Wildgeflügelbraten beibringen und dann sehen wir mal, was Ihr so draufhabt.", completion = "Ausdauer und Durchhaltevermögen sind die Voraussetzung, um alles Mögliche zu meistern. Sich an einem heißen Ofen abzurackern erfordert Geduld, die Ergebnisse sind die Mühen aber mehr als wert.", sourceObjectiveStatus = "unverified-source-field" }
quests[31478] = { id = 31478, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Weg des Ofens", description = "Wenn Ihr auf der Suche nach einer herzhaften Mahlzeit seid, die Euch lange sättigt und Eure Ausdauer erhöht, solltet Ihr Euch in den Weg des Ofens einweisen lassen. Bringt der Meisterin des Ofens einige Stücke Wildgeflügelbrust und sie wird Euch unterweisen. Im Tal der Vier Winde und im Jadewald leben viele Kraniche, doch auch von anderen Vögeln könnt Ihr Wildgeflügelbrust erjagen.", sourceObjective = "Bringt 5 Stück Wildgeflügelbrust zur Meisterin des Ofens.", progress = "Wenn Ihr Wildgeflügelbraten zubereiten wollt, benötigt Ihr einige Stücke Wildgeflügelbrust.", completion = "Hiermit können wir etwas anfangen.", sourceObjectiveStatus = "unverified-source-field" }
quests[31479] = { id = 31479, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Weg des Gebräus", description = "Der pandarische Weg des Gebräus produziert... nun, das lasse ich wohl am besten den Meister des Gebräus erklären. Bringt ihm ein wenig Ginseng und er wird Euch den Weg zeigen.", sourceObjective = "Bringt 1 Ginseng zum Meister des Gebräus. Ginseng kann von Sunghshin Eisentatz erworben werden.", progress = "Ihr wollt den Weg des Gebräus erlernen?", completion = "Das ist ein sehr schöner Ginseng. Wollt Ihr lernen, wie man daraus Tee kocht?", sourceObjectiveStatus = "unverified-source-field" }
quests[31480] = { id = 31480, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tut Euch was Gutes", description = "Meine Geschwister sind immer so ernst. Ich finde, das Leben ist viel zu kurz, um die ganze Zeit ernst zu sein. Trinkt doch einen Schluck Ginsengtee mit mir. Ich werde Euch zeigen, wie man ihn zubereitet.", sourceObjective = "Erlernt das Rezept für Ginsengtee vom Meister des Gebräus und bereitet dann 1 Tee für ihn zu.", progress = "Lasst mich Euch beibringen, wie man Ginsengtee zubereitet.", completion = "Sehr gut. Der Tee ist köstlich.", sourceObjectiveStatus = "unverified-source-field" }
